window.POEM_DB=window.POEM_DB||{};POEM_DB["song_039"]={"n":"白玉蟾","dyn":"宋","poems":[{"t":"春兴 其一","f":"七言绝句","c":["草根未放晓霜稀，骤冷初暄蝶倦飞。","行到碧桃花下看，新花良是旧枝非。"]},{"t":"春晚行乐 其一","f":"七言绝句","c":["一点春山一点愁，一丝暮雨一声鸠。","病中况更缘诗苦，夜去可堪无酒休。"]},{"t":"次韵王御带","f":"词","c":["晓风吹醒桃花醉，暮雨添成柳叶愁。","醉了又愁愁又醉，莺煎燕?过春休。"]},{"t":"胡中隐庵中伤春","f":"七言律诗","c":["尽把天工付祝融，东皇归去太华宫。","棱棱山色耸苍玉，湛湛波光浸碧铜。","杨柳入天鸠要雨，海棠落地蝶嫌风。","好将杖屦西园看，万紫千红一夜空。"]},{"t":"夏五即事 其二","f":"七言律诗","c":["晓来掠面更东风，过尽溪山属祝融。","杨柳引教荷芰绿，海棠让与石榴红。","稻针刺水连青亩，麦浪翻云涨碧空。","我有浮瓜沉李约，诸君同上紫霄峰。"]},{"t":"九曲杂咏 一曲升真洞","f":"七言绝句","c":["得得来寻仙子家，升真洞口正蜂衙。","一溪春水漾寒碧，流出红桃几片花。"]},{"t":"七女峰","f":"七言绝句","c":["宋时松竹晋时苔，路转山回洞户开。","流水也知尘世杂，依然流向此山来。"]},{"t":"七仙寺石履 其二","f":"七言绝句","c":["古人参罢祖师禅，已證如如不动尊。","想见脚根坚似铁，履鞋化石俨然存。"]},{"t":"七仙寺石履 其一","f":"七言绝句","c":["踏遍三千及大千，除非铁脚始能穿。","当时达磨持归去，何事传来到七仙。"]},{"t":"七台山","f":"七言绝句","c":["六月泉声带雨寒，斜阳染出淡红山。","白云无恙青枫老，不见龚刘振锡镮。"]},{"t":"九曲杂咏 七曲石塘寺","f":"七言绝句","c":["高僧参透赵州禅，拔寺移归兜率天。","天圣二年四月朔，一宵雷雨撼山川。"]},{"t":"九曲杂咏","f":"七言绝句","c":["流水光中飞落叶，白云影里噪幽禽。","人间几度曾孙老，只有青山无古今。"]},{"t":"九曲棹歌 其十 九曲","f":"七言绝句","c":["山市晴岚天打围，一村鸡犬正残晖。","稻田高下如棋局，几点鸦飞与鹭飞。"]},{"t":"九曲棹歌 其九 八曲","f":"七言绝句","c":["几点沙鸥泛碧流，芦花两岸暮云愁。","鼓楼岩下一声笛，惊落梧桐飞起秋。"]},{"t":"九曲棹歌 其八 七曲","f":"七言绝句","c":["寂寂秋烟锁碧湾，往年此地有禅关。","水神移入龙宫去，一夜风雷吼万山。"]},{"t":"九曲棹歌 其七 六曲","f":"七言绝句","c":["仙掌峰前仙子家，客来活火煮新茶。","主人摇指青烟里，瀑布悬崖剪雪花。"]},{"t":"九曲棹歌 其六 五曲","f":"七言绝句","c":["闻道谁知铁笛声，石崖轰裂老龙惊。","当年人已服丹去，千古荒亭秋草生。"]},{"t":"九曲棹歌 其五 四曲","f":"七言绝句","c":["万顷秋光无著处，满潭清水瑩青铜。","金鸡叫落山头月，淡淡寒烟飒飒风。"]},{"t":"九曲棹歌 其四 三曲","f":"七言绝句","c":["仙舟停棹架岩头，黄鹤归天今几秋。","满洞桃花人不见，一溪绿水为谁流。"]},{"t":"九曲棹歌 其三 二曲","f":"七言绝句","c":["山下于今几代孙，当时箫鼓寂无闻。","丹炉复尔生春草，玉女峰前空白云。"]},{"t":"九曲棹歌 其二 一曲","f":"七言绝句","c":["幔亭峰下泛仙船，洞口琼花锁翠烟。","一自魏王归绛阙，至今哀怨岭头猿。"]},{"t":"九曲棹歌 其一 武夷","f":"七言绝句","c":["三十六峰真绝奇，一溪九曲碧涟漪。","白云遮眼不知处，谁道神仙在武夷。"]},{"t":"九曲杂咏 九曲新村市","f":"七言绝句","c":["落日移舟上碧滩，桃花林外见青山。","耳边忽尔闻鸡犬，不遇刘郎不肯还。"]},{"t":"九曲杂咏 八曲鼓楼岩","f":"七言绝句","c":["万丈高岩耸石楼，云翚烟桷瞰寒流。","幔亭昔聚曾孙宴，石鼓拿归古渡头。"]},{"t":"卜居","f":"五言绝句","c":["路似羊肠绕，溪如燕尾分。","青山相领略，许我一丘云。"]},{"t":"九曲杂咏 三曲仙机岩","f":"七言绝句","c":["织就霓裳御泠风，玉梭随手化成龙。","天孙归去星河畔，满洞白云机杼空。"]},{"t":"上元玩灯 其二","f":"七言绝句","c":["上界天官此按行，五云深处有箫笙。","一轮宝月明如昼，万斛金莲开满城。"]},{"t":"上元玩灯 其一","f":"七言绝句","c":["碧玉融成万里天，满城罗绮竞春妍。","柳梢挂月黄昏后，夜市张灯白昼然。"]},{"t":"上清宫方丈后亭","f":"七言绝句","c":["三四声猿叫落月，六七竿竹呼起风。","夜静无人知此味，还他方丈拙庵翁。"]},{"t":"与永兴观主梅 其二","f":"七言绝句","c":["玉艳冰英绝可怜，即之时复一嫣然。","姑苏日暮逢西子，采石江明见谪仙。"]},{"t":"与永兴观主梅 其一","f":"七言绝句","c":["破袖悬鹑鬓㖀苍，山前山后乐相羊。","三更月影如酥白，一树梅花似雪香。"]},{"t":"与赵寺丞","f":"七言绝句","c":["汞铅不在身中取，龙虎当于意外求。","会得这些真造化，何愁不晓炼丹头。"]},{"t":"与赵将军 其三","f":"七言绝句","c":["芒鞋布袜与青藜，朝市迷心忽几时。","料得山中猿鹤冷，多应相怨不相思。"]},{"t":"与赵将军 其二","f":"七言绝句","c":["醉头一月不曾梳，共整扁舟又太湖。","昔日舞雩多一唯，他人陋巷只如愚。"]},{"t":"与赵将军 其一","f":"七言绝句","c":["见君除授千牛贵，过眼光荣一蠓微。","人爵未如天爵美，脂韦只道布韦非。"]},{"t":"夕眺风泉亭 其三","f":"七言绝句","c":["西风黄叶夕阳村，山水苍寒雾霭昏。","手撚菊花都是泪，枯松骨立绿毛鬈。"]},{"t":"夕眺风泉亭 其二","f":"七言绝句","c":["拄杖相寻访夕阳，诗肩独耸到昏黄。","白蘋洲上西风起，黄叶声中秋意长。"]},{"t":"夕眺风泉亭 其一","f":"七言绝句","c":["苒苒斜阳恋竹边，秋阴惨昧响寒泉。","如何今夜成无月，却遣西风一问天。"]},{"t":"山中偶成 其二","f":"七言绝句","c":["长日扃门坐小亭，松阴竹影自清清。","山翁莫问吾名姓，天上星辰地下行。"]},{"t":"山中偶成 其一","f":"七言绝句","c":["酒恶频频嗅素馨，满天风雨晚凉生。","岩花乱落无一点，谷鸟时闻啼数声。"]},{"t":"山居","f":"五言绝句","c":["月落鸡吹角，夜长鹅报更。","山中无历日，日出即天明。"]},{"t":"山居 其五","f":"七言绝句","c":["天静无尘夜半时，鹊乌啼罢众星稀。","数峰明月光无尽，一洞闲云淡不飞。"]},{"t":"山居 其四","f":"七言绝句","c":["竹风瑟瑟野猿号，月下酣眠不脱蓑。","恐致丹炉伤白蚁，懒烧松烛惜飞蛾。"]},{"t":"山居 其三","f":"七言绝句","c":["一片幽心卧紫霞，松梢凝翠夕阳斜。","尚无心绪听啼鸟，那有工夫扫落花。"]},{"t":"山居 其二","f":"七言绝句","c":["楮衾滴破松梢露，草屦淘穿石缝泉。","猿在岭头声未断，道人月下伴云眠。"]},{"t":"山居 其一","f":"七言绝句","c":["松竹成林云气深，洞门风冷绿苔阴。","落花飞尽青山在，幽鸟声中野客心。"]},{"t":"山前行散","f":"五言绝句","c":["人在莺花里，春归杖屦中。","风迎何处鹤，宿我洞门松。"]},{"t":"山前散策","f":"五言绝句","c":["月影黄昏后，诗天眼界宽。","野香寻得见，石背一枝兰。"]},{"t":"山斋夜坐 其二","f":"五言绝句","c":["惊梦猿三咽，窥帷月一痕。","无人空犬吠，依旧掩柴门。"]},{"t":"山斋夜坐 其一","f":"五言绝句","c":["嗅花风入鼻，掬水月浮身。","夜静焚香坐，空山一个人。"]},{"t":"山庵晓色","f":"五言绝句","c":["烛影夺明月，钟声撞晓云。","瓷盘馀柏子，倾作一炉焚。"]},{"t":"山歌","f":"七言绝句","c":["几家娘子守黄昏，多少郎君醉打门。","睡了不知明月好，三更三点似金盆。"]},{"t":"山歌 其三","f":"七言绝句","c":["人来人去唱歌行，只道灯明不月明。","月不如灯灯胜月，不消观月但观灯。"]},{"t":"山歌 其二","f":"七言绝句","c":["典钗卖钏买中秋，买得中秋醉又休。","明日酒醒无米煮，儿啼妻怨甚来由。"]},{"t":"山歌 其一","f":"七言绝句","c":["中秋夜月白如银，照见东西南北人。","古往今来人自老，月生月落几番新。"]},{"t":"飞云顶","f":"七言绝句","c":["飞云顶上阁阑干，夜半南溟出玉盘。","捲起水帘三百尺，松风吹度铁桥寒。"]},{"t":"飞行 其二","f":"七言绝句","c":["剑光长笑古刘家，不斩流星只斩蛇。","从得历年三四百，蟠桃犹自未开花。"]},{"t":"飞行 其一","f":"七言绝句","c":["飞行三十六天门，我是东华上相孙。","戏把蟠桃剜出核，玉童持去种昆崙。"]},{"t":"中秋","f":"七言绝句","c":["风卷青天落大江，江风江水自舂撞。","万千人看中秋月，十二楼开八面窗。"]},{"t":"中秋月","f":"七言绝句","c":["千崖爽气已平分，万里青天辗玉轮。","好向钱塘江上望，相逢都是广寒人。"]},{"t":"中秋月 其二","f":"七言绝句","c":["钱唐江上雪飞花，人在天边泛海槎。","乌鹊一声星斗落，姮娥梳洗去谁家。"]},{"t":"中秋月 其一","f":"七言绝句","c":["风吹玉露洗银河，爽气平分桂影高。","把笛倚楼人不寝，此心直拟数秋毫。"]},{"t":"为禅悟剪发偈","f":"七言绝句","c":["一毛头上一如来，一一如来鼻孔开。","把得这般刀在手，剪教断了唤教回。"]},{"t":"书怀 其二","f":"七言绝句","c":["山色未教晴日染，松声时听晚风梳。","韶光九十去无几，春雨春烟锁翠芜。"]},{"t":"书怀 其一","f":"七言绝句","c":["一春十病九因酒，三月都无两日晴。","明旦乘驴芳草路，绿杨深处听啼莺。"]},{"t":"九曲杂咏 五曲铁笛亭","f":"七言绝句","c":["满天沆瀣起清风，白鹤飞来上翠松。","月冷山空吹铁笛，一声唤起玉渊龙。"]},{"t":"五夜","f":"五言绝句","c":["五夜风吹露，林间鸟唤群。","钟声和月落，惊起四山云。"]},{"t":"九曲杂咏 六曲仙掌峰","f":"七言绝句","c":["仙子扪萝上翠崖，岩头旧有炼丹台。","至今石上留仙掌，十指春葱渍绿苔。"]},{"t":"六铢 其五","f":"五言绝句","c":["我醉辄指麾，莫向太帝说。","要炼五彩石，去补西天缺。"]},{"t":"六铢 其四","f":"五言绝句","c":["我著紫绮裘，俯视蓬莱洲。","手把八空气，纵身云中游。"]},{"t":"六铢 其三","f":"五言绝句","c":["紫皇坐瑶台，敕我草洞章。","落笔三百首，饮我白玉浆。"]},{"t":"六铢 其二","f":"五言绝句","c":["人间百春秋，天上一昼夜。","六丁驱日轮，长过咸池下。"]},{"t":"六铢 其一","f":"五言绝句","c":["身衣六铢衣，笑折琼林花。","岂知人间世，有人服苧麻。"]},{"t":"凤箫阁玩月 其四","f":"七言绝句","c":["凤箫吹断无人见，但有寒光拂太虚。","仰面笑天天亦笑，此心如月月何如。"]},{"t":"凤箫阁玩月 其三","f":"七言绝句","c":["画阁岿然百尺危，吹来花片点春衣。","黄昏璧月溪心浴，白昼银盘水面飞。"]},{"t":"凤箫阁玩月 其二","f":"七言绝句","c":["暮霭收无归鸟尽，凤箫阁上听松涛。","宿枝不稳鸦飞起，照水当中月上高。"]},{"t":"凤箫阁玩月 其一","f":"七言绝句","c":["一醉高寒清到骨，四无尘滓月当空。","光芒万里今犹昔，牢落十年西复东。"]},{"t":"午顿","f":"七言绝句","c":["笋方合爪蕨擎拳，好与同参诗里禅。","居士闻韶今已久，炉峰为我晓生烟。"]},{"t":"双莲","f":"七言绝句","c":["一池莲菡漾红霞，并带双花足赏嗟。","醉面相看谁得似，三郎夜饮玉真家。"]},{"t":"双溪馆","f":"七言绝句","c":["两点文章翰墨星，夜翱双鹤入青冥。","楼前为忆张华剑，八百年来无血腥。"]},{"t":"天窗","f":"七言绝句","c":["屋头除却数条椽，政好临风对月眠。","行客只从门外过，岂知屋里有青天。"]},{"t":"忆西湖","f":"七言绝句","c":["银月窥人夜漏沉，断蒲疏柳忽关心。","西风为报西湖道，留取芙蓉供醉吟。"]},{"t":"忆鹤","f":"七言绝句","c":["洞里不知城市改，人间再到子孙非。","有谁尚自看华表，何处如今叫令威。"]},{"t":"月夕书事","f":"七言绝句","c":["悲秋念远夜将阑，黄叶乘风直斩关。","微白一钩天外月，淡青数点海边山。"]},{"t":"月夜书事","f":"五言绝句","c":["月光流如酥，天影湛于水。","饥鹤啄梅花，风吹酒波起。"]},{"t":"木犀","f":"五言绝句","c":["雨送炎官印，风宣白帝麻。","欲知秋面目，细看木犀花。"]},{"t":"水村吟雾","f":"七言绝句","c":["淡处还浓绿处青，江风吹作雨毛腥。","起从水面萦层嶂，恍似帘中见画屏。"]},{"t":"水蛭","f":"五言绝句","c":["屋宅才蜗大，身躯与蚓般。","楚王吞不得，敕赐鹭鸶餐。"]},{"t":"水团","f":"七言绝句","c":["火宅煎熬不自由，就中涝漉几沉浮。","翻身得入清凉国，也合甘心吃水休。"]},{"t":"牛渡问舟","f":"七言绝句","c":["岁晚行人苦欲分，山昏水暮鸟寻群。","舟行棹进空回首，一望苍梧但白云。"]},{"t":"见莺 其三","f":"七言绝句","c":["一莺飞去一莺啼，桃李一空春已归。","踏破苍苔殊可惜，坐看流水拽斜晖。"]},{"t":"见莺 其二","f":"七言绝句","c":["鲜怡寡乐负清明，帘外花如红泪倾。","又是残春将立夏，如何到处不啼莺。"]},{"t":"见莺 其一","f":"七言绝句","c":["夜来新长水三尺，雨过横流春一溪。","翠柳颦眉花阁泪，乳莺空对妇鸠啼。"]},{"t":"风台遣心 其三","f":"五言绝句","c":["青尽池边柳，红开槛外花。","数时长病酒，今日且分茶。"]},{"t":"风台遣心 其二","f":"五言绝句","c":["鸦报千林晓，梅供一枕香。","晓来春思倦，馀梦尚悠扬。"]},{"t":"风台遣心 其一","f":"五言绝句","c":["春色浓于酒，梅花瘦似诗。","长青今岁叶，粲白去年枝。"]},{"t":"风窗","f":"五言绝句","c":["窗隙针来大，霜风圣得知。","耳边如箭急，直把菊花吹。"]},{"t":"东山道院","f":"七言绝句","c":["烟月荒凉野色寒，松梢滴露夜将阑。","人家旷绝无鸡犬，一鹤飞来点翠山。"]},{"t":"仙居楼","f":"七言绝句","c":["万籁沉沉清夜阑，楼前独自倚栏干。","金鸡叫罢松风动，三十六天秋月寒。"]},{"t":"仙岩无尘轩","f":"五言绝句","c":["麈尾清虚语，铜炉起澹烟。","岭头猿叫罢，月落碧潭圆。"]},{"t":"冬夕酌月 其三","f":"七言绝句","c":["二毛可惜雪霜侵，日有清都绛阙心。","枝冷鹊翻檐外影，庭空鸿堕月边音。"]},{"t":"冬夕酌月 其二","f":"七言绝句","c":["兔冷蟾寒桂影疏，化为霜露泻庭除。","已惊柏液冰吾齿，莫弄梅花粟尔肤。"]},{"t":"冬夕酌月 其一","f":"七言绝句","c":["半规新月滑如酥，流入清樽一吸无。","明日定知广寒殿，姮娥失却水晶梳。"]},{"t":"冬暮","f":"五言绝句","c":["风落松梢雪，山收竹外烟。","清吟凝醉眼，独立耸新肩。"]},{"t":"对月 其六","f":"七言绝句","c":["山似愁眉烟画翠，月如醉眼晕生红。","鹤雏踏碎芙蓉影，酒思诗情渺碧空。"]},{"t":"对月 其五","f":"七言绝句","c":["早已棋中悟死生，不须须上看勋名。","风吹酒面秋情眇，月透诗肠夜未清。"]},{"t":"对月 其四","f":"七言绝句","c":["水澄熊白成壶酒，枫染猩红满路旗。","坐待西风迎素月，青天笑我独诗痴。"]},{"t":"对月 其三","f":"七言绝句","c":["烟颦雨蹙到今朝，嫩火温香破寂寥。","月下饮残千日酒，云间吹断一声箫。"]},{"t":"对月 其二","f":"七言绝句","c":["醉袖舞低千嶂月，清歌遏住九天云。","鸿归燕去伤秋老，鹤唳猿啼觉夜分。"]},{"t":"对月 其一","f":"七言绝句","c":["深秋荷败柳枯时，霜蟹香枨副所思。","月要人窥娇不上，风知我醉放多吹。"]},{"t":"玉艳亭即事 其五","f":"五言绝句","c":["风雨平安日，山林富贵天。","笋芽青露爪，蕨蕻紫伸拳。"]},{"t":"玉艳亭即事 其四","f":"五言绝句","c":["犬见行人吠，牛寻熟路回。","烟光迷碧嶂，花片点苍苔。"]},{"t":"玉艳亭即事 其三","f":"五言绝句","c":["黄鸟新声变，青山霁色妍。","预为寒食地，晴放海棠天。"]},{"t":"玉艳亭即事 其二","f":"五言绝句","c":["夙酒萦怀处，芳亭拄颊间。","一莺黄翠柳，双鹭白青山。"]},{"t":"玉艳亭即事 其一","f":"五言绝句","c":["正月梅花尽，一溪春雨香。","燕方寻故垒，蜂已葺华房。"]},{"t":"示如净讲主","f":"七言绝句","c":["浩浩春风泛碧梧，娟娟秋水照芙蕖。","大师佛法无多子，居士身心本一如。"]},{"t":"示周道士","f":"七言绝句","c":["前山隐隐起雷声，细雨丝丝濯旱氛。","何处飞来松上鹤，晚风唳断九天云。"]},{"t":"示周道士","f":"五言绝句","c":["人行秋色里，诗入画图中。","笑指白云顶，猿啼第一峰。"]},{"t":"示英州风僧","f":"七言绝句","c":["宗门老衲旧仪刑，配字年来老转青。","谁道南能无一物，如今英石尽铜腥。"]},{"t":"立马待舟","f":"七言绝句","c":["拂晓匆匆马首东，嫩寒初破酒无功。","自知雾帽清珠湿，少立霜桥脆玉松。"]},{"t":"立春","f":"五言绝句","c":["颛帝位方禅，勾芒印已交。","芭蕉有封事，黄鸟莫譊譊。"]},{"t":"元旦在鹤林偶作","f":"七言绝句","c":["东风吹散柳梢雪，一夜挽回天下春。","从此阳春应有脚，百花富贵草精神。"]},{"t":"龙井","f":"七言绝句","c":["山腰石有千年润，海眼泉无一日乾。","天下苍生望霖雨，不知龙在此中蟠。"]},{"t":"龙虎山祈雨早行有作","f":"七言绝句","c":["两三条电复无雨，六七点星微上云。","鞭起卧龙我骑去，挥戈叱问五雷君。"]},{"t":"龙潭 其二","f":"七言绝句","c":["惊崖却立挨斜日，老桧前临接断烟。","水鸟负暄闲整翼，山禽相贺已晴天。"]},{"t":"龙潭 其一","f":"七言绝句","c":["尖峰簇簇穿林笋，曲径盘盘绕树藤。","中有古潭深万丈，老龙独卧似禅僧。"]},{"t":"伤春词寄紫元 其四","f":"七言绝句","c":["望眼生花泪已枯，青衣也合递归书。","客情无奈春风雨，更问春空有雁无。"]},{"t":"伤春词寄紫元 其三","f":"七言绝句","c":["孤村古馆雨凄凄，客里愁闻乌夜啼。","枕冷衾寒才闭目，春风吹转梦魂迷。"]},{"t":"伤春词寄紫元 其二","f":"七言绝句","c":["幽人何事苦伤春，春雨无端愁杀人。","不但幽人独愁怨，江头多少柳眉颦。"]},{"t":"伤春词寄紫元 其一","f":"七言绝句","c":["幽人抱膝掩柴门，八九渔家烟水村。","坐对青山两无语，春风春雨送黄昏。"]},{"t":"冲虚侍宸王文卿像赞","f":"七言绝句","c":["醉持铁尺叫风雷，玉帝纶言召两回。","到得人间无鬼蜮，依然长啸入西台。"]},{"t":"华阳吟 其十四","f":"七言绝句","c":["一吟一醉一刀圭，真气真精满四肢。","若到酒酣眠熟后，满船载宝过曹溪。"]},{"t":"华阳吟 其三十","f":"七言绝句","c":["拈弄溪山诗伎巧，吐吞风月酒神通。","且将诗酒瞒人眼，出入红尘过几冬。"]},{"t":"华阳吟 其二十九","f":"七言绝句","c":["梦幻之身不久长，桑榆能几耐风霜。","何如跳出利名窟，赠汝长生不死方。"]},{"t":"华阳吟 其二十八","f":"七言绝句","c":["气盖山河心胆粗，不能学剑不搜书。","夜来掇得乾坤动，火候温温守玉炉。"]},{"t":"华阳吟 其二十七","f":"七言绝句","c":["家在神仙九气天，天中楼殿贮群仙。","偶然来到人间世，料想神霄未一年。"]},{"t":"华阳吟 其二十六","f":"七言绝句","c":["绛阙仙都一散郎，偶来尘世且佯狂。","身中自有长生宝，夜夜飞神谒上苍。"]},{"t":"华阳吟 其二十五","f":"七言绝句","c":["祇将戊己作丹炉，炼得红丸化玉酥。","漫守火爻三百日，产成一颗夜明珠。"]},{"t":"华阳吟 其二十四","f":"七言绝句","c":["曹溪一路透泥丸，只在丹田上下间。","解使金翁媒姹女，朝云暮雨满巫山。"]},{"t":"华阳吟 其二十三","f":"七言绝句","c":["玉皇殿下一仙童，曾掌符书守蕊宫。","因甚俗缘犹未断，于今幻质入尘笼。"]},{"t":"华阳吟 其二十二","f":"七言绝句","c":["昨夜三更雷撼山，九天门户不曾关。","曹溪路上分明见，有个金乌入广寒。"]},{"t":"华阳吟 其二十一","f":"七言绝句","c":["谁识周天造化工，于今蹙在片时中。","只将铅汞入真土，炼出金花满鼎红。"]},{"t":"华阳吟 其二十","f":"七言绝句","c":["不动丝毫过玉关，关头自有玉京山。","能于山上通来往，风搅九天霜雪寒。"]},{"t":"华阳吟 其十九","f":"七言绝句","c":["一泓神水满华池，夜夜池边白雪飞。","雪里有人擒玉兔，赶教明月上寒枝。"]},{"t":"华阳吟 其十八","f":"七言绝句","c":["片饷工夫炼汞铅，一炉猛火夜烧天。","忽然神水落金井，打合灵砂月样圆。"]},{"t":"华阳吟 其十七","f":"七言绝句","c":["青牛人去几多年，此道分明在目前。","愿识目前真的处，一堂风冷月婵娟。"]},{"t":"华阳吟 其十六","f":"七言绝句","c":["饥餐一两黑龟肝，寒向丹田猛火山。","但见心头无点事，不知人世有饥寒。"]},{"t":"华阳吟 其十五","f":"七言绝句","c":["元神夜夜宿丹田，云满黄庭月满天。","两个鸳鸯浮绿水，水心一朵紫金莲。"]},{"t":"华阳吟 其十三","f":"七言绝句","c":["怪事教人笑几回，男儿今也会怀胎。","自家精血自交媾，身里夫妻真妙哉。"]},{"t":"华阳吟 其十二","f":"七言绝句","c":["人身自有一蓬莱，十二层楼白玉阶。","姹女金翁常宴会，堂前夜夜牡丹开。"]},{"t":"华阳吟 其十一","f":"七言绝句","c":["戏泛金船到海涯，暗随海水度流沙。","一从登著蓬莱岸，去看琼台阆苑花。"]},{"t":"华阳吟 其十","f":"七言绝句","c":["移将北斗过南辰，两手双擎日月轮。","飞趁昆崙山上去，须臾化作一天云。"]},{"t":"华阳吟 其九","f":"七言绝句","c":["渴饮金波数百钟，醉时仗剑指虚空。","脚根戏蹑交乾斗，长啸一声天地红。"]},{"t":"华阳吟 其八","f":"七言绝句","c":["白马江头笑一声，红光紫雾水中生。","急抽匣内青蛇剑，搅得黄河彻底清。"]},{"t":"华阳吟 其七","f":"七言绝句","c":["得诀归来试炼看，龙争虎斗片时间。","九华天上人知得，一夜风雷撼万山。"]},{"t":"华阳吟 其五","f":"七言绝句","c":["拄杖随身入武夷，幔亭峰下雪花飞。","行从九曲山头看，万壑千岩翠打围。"]},{"t":"华阳吟 其四","f":"七言绝句","c":["白云和我到天台，眼入青山意豁开。","到彼山中结茅屋，空馀千古夜猿哀。"]},{"t":"华阳吟 其三","f":"七言绝句","c":["一脚从别海南船，身逐云飞江浙天。","走遍洞天寻隐者，不知费几草鞋钱。"]},{"t":"华阳吟 其二","f":"七言绝句","c":["海南一片水云天，望眼生花已十年。","忽一二时回首处，西风夕照咽悲蝉。"]},{"t":"华阳吟 其一","f":"七言绝句","c":["家在琼崖万里遥，此身来往似孤舟。","夜来梦趁西风去，目断家山空泪流。"]},{"t":"同邓孤舟林片雪二友晚吟 其三","f":"七言绝句","c":["江天漠漠但黄芦，雁鹜相呼日已晡。","雨过月如全赵璧，烟深山似绐秦图。"]},{"t":"同邓孤舟林片雪二友晚吟 其二","f":"七言绝句","c":["君非爱此数峰青，肯恋扁舟尚蓼汀。","群雁横空成一字，孤萤度水似双星。"]},{"t":"同邓孤舟林片雪二友晚吟 其一","f":"七言绝句","c":["扁舟如叶片帆孤，少霁临江得句无。","雨竹似人扶酒病，风松学我撚吟须。"]},{"t":"安仁县问宿","f":"七言绝句","c":["幕燕翻雷天作云，一声归鸟万林昏。","荒城寂寞无堪酒，灯下支颐雨打门。"]},{"t":"戏鹤林","f":"七言绝句","c":["柱下固能官老子，漆园亦可禄庄周。","鹤林不仕知何意，快取青毡趁黑头。"]},{"t":"早行","f":"五言绝句","c":["店远鸡声近，月斜人影长。","再三谢风露，拜赐一天凉。"]},{"t":"早秋","f":"七言绝句","c":["云来云去状秋阴，细雨笼晴夕照沉。","半夜月明千籁静，一声猿叫万山深。"]},{"t":"曲肱诗 其二十","f":"七言绝句","c":["桑田变海海成田，这话教人信也难。","只有一般输我处，君王未有此清闲。"]},{"t":"曲肱诗 其十九","f":"七言绝句","c":["不把双眸看俗人，五湖四海一空身。","洞天深处无人到，溪上桃花几度春。"]},{"t":"曲肱诗 其十八","f":"七言绝句","c":["不识看经不坐禅，饥来吃饭困来眠。","玉皇若不开青眼，却是凡夫骨未仙。"]},{"t":"曲肱诗 其十七","f":"七言绝句","c":["我有随身一颗珠，见时似有觅时无。","金鸡叫罢无人见，月射寒光满太虚。"]},{"t":"曲肱诗 其十六","f":"七言绝句","c":["这回空过二十年，肉重不能飞上天。","抖擞衲头还自笑，囊中也没一文钱。"]},{"t":"曲肱诗 其十五","f":"七言绝句","c":["跣足蓬头破衲衣，闷来饮酒醉吟诗。","廛中走遍无人识，我是东华大帝儿。"]},{"t":"曲肱诗 其十四","f":"七言绝句","c":["说与清风明月知，扬州有鹤未能骑。","夜来五凤楼前看，天上白云空自飞。"]},{"t":"曲肱诗 其十三","f":"七言绝句","c":["白云随我见天台，又趁金华路上回。","栖凤亭中留不去，武夷山下野猿哀。"]},{"t":"曲肱诗 其十二","f":"七言绝句","c":["做到天仙地位时，三遭天谴落天墀。","却嫌天上多官府，且就人间洞府嬉。"]},{"t":"曲肱诗 其十一","f":"七言绝句","c":["往昔逍遥在太华，朝餐玉乳看琼花。","当年身著六铢服，不识人间有苧麻。"]},{"t":"曲肱诗 其十","f":"七言绝句","c":["我到人间未百年，恰如顷刻在三天。","向来我本雷霆吏，今更休疑作甚仙。"]},{"t":"曲肱诗 其九","f":"七言绝句","c":["瑶池王母宴群仙，两部笙歌簇绮筵。","误取一枚仙李吃，又来人世不知年。"]},{"t":"曲肱诗 其八","f":"七言绝句","c":["玉府官僚无甚人，上皇怜我最辛勤。","忽然诏下催归去，猿叫万山空白云。"]},{"t":"曲肱诗 其七","f":"七言绝句","c":["梦断南柯觉昨非，因缘尽处两分飞。","寒松空锁翠娥梦，我独于今未得归。"]},{"t":"曲肱诗 其六","f":"七言绝句","c":["我不生嗔怨玉皇，翠娥无复舞霓裳。","如何天上神仙女，染污清都一散郎。"]},{"t":"曲肱诗 其五","f":"七言绝句","c":["太乙天皇谒紫清，翠娥百万拥云軿。","当时不合抬头看，忽见天丁叱火铃。"]},{"t":"曲肱诗 其四","f":"七言绝句","c":["五雷深锁玉清宫，白鹤呼风唳碧空。","说著这般辛苦处，三千玉女蹙眉峰。"]},{"t":"曲肱诗 其三","f":"七言绝句","c":["谪君尘世意徘徊，炼尽金丹待鹤来。","归去神霄朝玉帝，依前命我掌风雷。"]},{"t":"曲肱诗 其二","f":"七言绝句","c":["玉皇有敕问神霄，谁去骑龙乱作妖。","自别雷城一回首，人间天上已相辽。"]},{"t":"曲肱诗 其一","f":"七言绝句","c":["昔在青华第一宫，祇缘醉后怒骑龙。","倾翻半滴金瓶水，不觉人间雨发洪。"]},{"t":"有怀聂尉 其五","f":"五言绝句","c":["剑浦犹残堠，螺江始问津。","向来风浪恶，回首谢灵均。"]},{"t":"有怀聂尉 其四","f":"五言绝句","c":["不是无知己，相忘独有君。","孤襟开皓月，往事付浮云。"]},{"t":"有怀聂尉 其三","f":"五言绝句","c":["月湿松梢露，溪鸣竹里风。","是中有诗味，何日一樽同。"]},{"t":"有怀聂尉 其二","f":"五言绝句","c":["北阙投封事，南山返故庐。","李衡千树橘，张琰一园蔬。"]},{"t":"有怀聂尉 其一","f":"五言绝句","c":["身岂能为患，心何可得安。","想应知鹤怨，未得伴鸥闲。"]},{"t":"次韵王将仕 其二","f":"七言绝句","c":["白雾重重山复山，山光树色有无间。","是中紫翠皆诗料，病起无聊著句难。"]},{"t":"次韵王将仕 其一","f":"七言绝句","c":["散发披襟乐醉乡，从朝笑语到斜阳。","坐来一片蝉声久，未信人间有此凉。"]},{"t":"霜夕吟月 其二","f":"七言绝句","c":["吟魂缥渺迈霜空，立影茕然翠阁东。","素喜半钩西面月，生憎一箭北头风。"]},{"t":"次韵永兴王宰游钟成观 其一","f":"七言绝句","c":["万斛苍烟恋钓矶，一川秋绿漾清晖。","空明隐映流光薄，翻忆当年苏紫微。"]},{"t":"次韵曾丈探梅","f":"七言绝句","c":["夜半风吹雪满阶，头巾不裹把窗开。","南枝暗就江头发，一点香从月下来。"]},{"t":"江上散纵","f":"七言绝句","c":["欲晓江头杖策徐，一峰西去众峰趋。","不知林里犹僧寺，少立忽闻敲木鱼。"]},{"t":"江口有怀 其二","f":"七言绝句","c":["丹枫偷落风无觉，白鹭微行鱼不知。","两地南楼今夜月，一般清皎百般思。"]},{"t":"江口有怀 其一","f":"七言绝句","c":["霜将枫绿染为红，风把芦花缕作茸。","云自幕天谁钉挂，月来佐酒与从容。"]},{"t":"江头","f":"五言绝句","c":["江上初收雨，云头尚恋山。","归帆巡古岸，晴草守沧湾。"]},{"t":"江亭夜坐","f":"七言绝句","c":["月冷松寒露满襟，天容绀碧鹤声沉。","夜深独把栏干拍，只有长江识此心。"]},{"t":"江楼夜话","f":"五言绝句","c":["江雾秋楼白，灯花夜雨青。","九天无一梦，此道付晨星。"]},{"t":"竹园 其三","f":"七言绝句","c":["自笑园丁职事新，一春风雨为供申。","笋如滕薛皆争长，瓜似朱陈已结亲。"]},{"t":"竹园 其二","f":"七言绝句","c":["一片琅玕香净天，风吹细细雨娟娟。","龙孙始学斑衣戏，鹙子从谈玉版禅。"]},{"t":"竹园 其一","f":"七言绝句","c":["可惜洋州不再生，此君只许伯夷清。","霜删近觉林方瘦，笋碍浑无路得行。"]},{"t":"竹里桃花","f":"七言绝句","c":["风吹雨洗玉猗猗，云捲霞舒锦陆离。","竹夹桃花花映竹，雅如翠障绣西施。"]},{"t":"红梅","f":"七言绝句","c":["明皇爱雪响云营，侍宴宫娃不计名。","守等太真眠未起，醺然秉烛到深更。"]},{"t":"自赞 其三","f":"五言绝句","c":["神府雷霆吏，琼山白玉蟾。","本来真面目，水墨写霜缣。"]},{"t":"自赞 其一","f":"五言绝句","c":["日月藏瓢里，溪山挂杖头。","有些难说处，夜夜是中秋。"]},{"t":"舟中晚眺 其二","f":"七言绝句","c":["不成无语立江滨，事事堪吟句句新。","白鹭前身真钓叟，青山今日是诗人。"]},{"t":"舟中晚眺 其一","f":"七言绝句","c":["小立船仓揭起篷，晚来帆幅饱西风。","望他鸿雁一双去，过了峰峦千万重。"]},{"t":"舟次吉溪","f":"七言绝句","c":["十年三过吉溪滩，想被溪梅笑往还。","尘暗壁间题迹旧，满斟杯酒慰寒山。"]},{"t":"舟行","f":"七言绝句","c":["山锁晓烟迷紫翠，花凝宿雨间青红。","快帆幸自泛秋绿，乞与一篙东去风。"]},{"t":"舟行","f":"七言绝句","c":["梢子欢呼御晓风，诗人亦自起推蓬。","数来数去山都乱，忘却前峰与后峰。"]},{"t":"舟程苦迟","f":"七言绝句","c":["水马轻便胜陆行，冲风溯水反多程。","溪流诘曲成千摺，云色阴晴没十成。"]},{"t":"行春辞 其九","f":"七言绝句","c":["宝马香车政踏青，岂知已自过清明。","燕雏告诉花都落，鸠妇丁宁雨速晴。"]},{"t":"行春辞 其八","f":"七言绝句","c":["绿杨无力暖相依，不管黄莺诉落晖。","水被鱼吹成雨点，花为蝶扰逐风飞。"]},{"t":"行春辞 其七","f":"七言绝句","c":["政是风娇日騃天，蔷薇粉褪海棠蔫。","贵人那得看花福，多在绿窗犹醉眠。"]},{"t":"行春辞 其六","f":"七言绝句","c":["终日寻春入醉乡，不知何处见春光。","风条舞绿水杨柳，雨点飞红山海棠。"]},{"t":"行春辞 其五","f":"七言绝句","c":["几日春功似有加，晓来万象尽排衙。","群莺主管园林事，一雨巡行桃李花。"]},{"t":"行春辞 其四","f":"七言绝句","c":["借彼笙箫鼓笛中，诗人随分得春风。","提壶处处差监酒，布谷朝朝讲劝农。"]},{"t":"行春辞 其三","f":"七言绝句","c":["园园是日是花开，我又何朝不醉来。","井有人焉蛙两部，日之夕矣蝶三台。"]},{"t":"行春辞 其一","f":"七言绝句","c":["一斗百篇诚有之，无人知我只春知。","吟逢蝴蝶即庄子，醉见海棠真贵妃。"]},{"t":"观物 其二","f":"七言绝句","c":["晓鹭守溪图口腹，暮蛛借屋计家生。","不羁野马空中骋，无喘蜗牛壁上耕。"]},{"t":"观物 其一","f":"七言绝句","c":["蜂占蔷薇封食邑，蚁侵蜾蠃借军须。","雨天风急鸠呼妇，水国烟寒雁唤奴。"]},{"t":"许天游见过","f":"七言绝句","c":["蝉外西风风外叶，雁边落日日边云。","诗仙世界无疆埸，一片青山共子分。"]},{"t":"许旌阳故宅","f":"五言绝句","c":["诗多唐代刻，柏尚晋时青。","想得真君剑，犹馀蛟血腥。"]},{"t":"过石梯","f":"七言绝句","c":["小伞轻包手自携，少需脚力过危梯。","入门失问翁高姓，看尽壁间前后题。"]},{"t":"问子规","f":"七言绝句","c":["绿柳阴中问子规，劝人归是劝春归。","人须回首春须暮，何不成都西去飞。"]},{"t":"问花","f":"七言绝句","c":["蓦地诗心到海棠，问花开未晓来忙。","村童熟睡不知唤，惟有流莺语似簧。"]},{"t":"问春","f":"七言绝句","c":["不教蜂蝶略来些，岂是春神病酒耶。","燕语莺啼今几日，风魔雨难许多花。"]},{"t":"华阳吟 其六","f":"七言绝句","c":["武夷结草二年馀，花笑莺啼春一壶。","流水下山人出洞，岩前空有炼丹炉。"]},{"t":"何仙姑赞","f":"五言绝句","c":["阆苑无踪迹，唐朝有姓名。","不知红玉洞，千古夜猿声。"]},{"t":"即事君子堂 其五","f":"七言绝句","c":["自点雌黄改自诗，苧衣不著著蕉衣。","前山何故枯松上，半月巢空鹤不归。"]},{"t":"即事君子堂 其四","f":"七言绝句","c":["枝头尚有烂黄梅，次第荷花白者开。","庭雀被人惊得惯，作群飞去又飞回。"]},{"t":"即事君子堂 其三","f":"七言绝句","c":["招风竹下凉生扇，弄水荷边香满衫。","自拾落花揩面汗，唤将红白酒相搀。"]},{"t":"即事君子堂 其二","f":"七言绝句","c":["南薰唤起莲花悟，西照催归燕子忙。","自洗霜刀来切藕，传君嚼玉咽冰方。"]},{"t":"即事君子堂 其一","f":"七言绝句","c":["墙头榴火正烧空，风削苍云作数峰。","避叶荷花如避暑，病香愁态若为容。"]},{"t":"听琴 其二","f":"五言绝句","c":["心造虚无外，弦鸣指甲间。","夜来宫调罢，明月满空山。"]},{"t":"听琴 其一","f":"五言绝句","c":["十指生秋水，数声弹夕阳。","不知君此曲，曾断几人肠。"]},{"t":"听琴 其三","f":"五言绝句","c":["声出五音表，弹超十指中。","鸟啼花落处，曲罢对春风。"]},{"t":"张楼","f":"七言绝句","c":["前度相逢一似曾，瘦宽金镯可怜生。","绿窗朱户如无恙，酌我百杯秋月明。"]},{"t":"折梅 其二","f":"七言绝句","c":["一朵寒香已自奇，高丫两朵更清姿。","树前树后花都绝，折了南枝折北枝。"]},{"t":"折梅 其一","f":"七言绝句","c":["夜半披衣凭玉栏，天风吹露洒琅玕。","前台后台月如水，云去云来梅影寒。"]},{"t":"护国寺秋吟 其八","f":"五言绝句","c":["星似萤千点，云如鹤一双。","孤吟寒不寐，落叶打空窗。"]},{"t":"护国寺秋吟 其七","f":"五言绝句","c":["香篆孤烟袅，灯龛寸火微。","梦和明月冷，心与白云飞。"]},{"t":"护国寺秋吟 其六","f":"五言绝句","c":["犬吠月如昼，马鸣人渡桥。","更无诗与酒，虚度可怜宵。"]},{"t":"护国寺秋吟 其五","f":"五言绝句","c":["竹手擎云重，松肩荷月高。","烟收天地阔，醉目数秋毫。"]},{"t":"护国寺秋吟 其四","f":"五言绝句","c":["嫩竹容归鹊，寒松捧落晖。","危红和露落，空翠扑衣飞。"]},{"t":"护国寺秋吟 其三","f":"五言绝句","c":["楼影秋江白，苔碑卧夕阳。","水昏沙暮起，一一雁南翔。"]},{"t":"护国寺秋吟 其二","f":"五言绝句","c":["酒弄三竿日，诗成一枕风。","寒声落鸿雁，秋意著梧桐。"]},{"t":"护国寺秋吟 其一","f":"五言绝句","c":["雁过天成画，鱼惊水作纹。","檐牙宵吐雨，殿脊晓驮云。"]},{"t":"李伯阳赞 其三","f":"五言绝句","c":["蓬莱三万里，道德五千言。","一自青牛去，函关烟雨昏。"]},{"t":"课园夫 其二","f":"五言绝句","c":["问我何厨传，珍鲜满故园。","笋方青剥指，茄欲紫垂拳。"]},{"t":"步自玉乳峰归 其一","f":"五言绝句","c":["薄暮一凝伫，归鸿千有馀。","倚松吟半饷，月影泻庭除。"]},{"t":"芙蓉","f":"五言绝句","c":["临水玩芙蓉，一花还两影。","上倚夕阳斜，下浸秋波冷。"]},{"t":"谷帘下 其二","f":"七言绝句","c":["步入青红紫翠间，仙翁朝斗有遗坛。","竹梢露重昼犹湿，松里云深夏亦寒。"]},{"t":"谷帘下 其一","f":"七言绝句","c":["紫岩素瀑展长霓，草木幽深雾雨凄。","竹里一蝉闻竹外，溪东双鹭过溪西。"]},{"t":"远景","f":"五言绝句","c":["岸树冥茫外，人家点画中。","断烟分紫翠，残照抹青红。"]},{"t":"闲吟 其三","f":"五言绝句","c":["啼鸟千山暮，轻风一路清。","草连江色暝，月对夕阳明。"]},{"t":"闲吟 其二","f":"五言绝句","c":["回首乌啼夜，伤心月满楼。","真成花命薄，不及柳风流。"]},{"t":"闲吟 其一","f":"五言绝句","c":["东园风雨霁，一巷海棠开。","曲折穿花去，深行忘却回。"]},{"t":"闲纵偶成","f":"五言绝句","c":["已具看云眼，而生伴月心。","西风相体认，红尽绿枫林。"]},{"t":"陈七子赞","f":"五言绝句","c":["一卷无人识，千钟对客谈。","桃花开欲谢，犹自恋寒岩。"]},{"t":"饮彻","f":"五言绝句","c":["美事般般四，良辰盏盏双。","霜风冰砚水，山月影轩窗。"]},{"t":"卧云","f":"七言绝句","c":["满室天香仙子家，一琴一剑一杯茶。","羽衣常带烟霞色，不惹人间桃李花。"]},{"t":"和刘司门韵题临溪亭","f":"七言绝句","c":["临水皤然两鬓丝，山烟凝翠入鹑衣。","横吹铁笛且归去，懒把渔竿立藓矶。"]},{"t":"咏雪","f":"七言绝句","c":["青女怀中酿雪方，雪儿为曲露为浆。","一朝雪熟飞廉醉，酘得东风一夜狂。"]},{"t":"咏韩湘","f":"七言绝句","c":["汝叔做尽死模样，雪里出来无意况。","赖有当年花一篮，至今推与闲和尚。"]},{"t":"夜半","f":"七言绝句","c":["夜半风吹远梦回，直从海上忽飞来。","回头但见山三点，彻席犹馀酒一杯。"]},{"t":"夜坐忆刘玉渊 其三","f":"楚辞体","c":["冰枯雪老尚天台，使我诗肠日九回。","归去来兮须岁暮，岁云暮矣不归来。"]},{"t":"夜坐忆刘玉渊 其二","f":"七言绝句","c":["夜已三更忽坐忘，吟魂醉魄政悠扬。","孤鸿见召听寒角，残月相辞过粉墙。"]},{"t":"夜坐忆刘玉渊 其一","f":"七言绝句","c":["多多泻酒愁无况，久久吟诗淡有情。","花作雪飞深一寸，月随云上恰三更。"]},{"t":"夜深","f":"七言绝句","c":["一晚寻思未得诗，楼前只有月相知。","夜深欲睡还贪坐，坐到五更钟动时。"]},{"t":"夜醉","f":"五言绝句","c":["鼕鼕珰珰珰，烂醉如泥了。","睡至谷谷呱，东窗梅影晓。"]},{"t":"奉酬臞庵李侍郎 其一","f":"七言绝句","c":["坐对梅花撚白须，吟边有酒不须酤。","松窗昨夜冰生砚，冻合银床读易朱。"]},{"t":"奉酬臞庵李侍郎 其二","f":"七言绝句","c":["南枝才放两三花，雪里吹香弄粉些。","淡淡著烟浓著月，深深笼水浅笼沙。"]},{"t":"奉酬臞庵李侍郎 其五","f":"七言绝句","c":["酒红沁面晕成霞，笑撚吟髭数暮鸦。","不入朝廷鸳鹭侣，自甘白发插梅花。"]},{"t":"奉酬臞庵李侍郎 其四","f":"七言绝句","c":["满月世界琉璃光，通宵不寐据胡床。","语言玉润篇篇锦，心胆冰清字字香。"]},{"t":"奉酬臞庵李侍郎 其三","f":"七言绝句","c":["全是山林居士风，不知位重更官穹。","名书玉几金瓯内，心在蒲团纸帐中。"]},{"t":"孤萤","f":"七言绝句","c":["夜静乘凉坐水亭，草头隐映见孤萤。","瞥然飞过银塘面，俯仰浮光几点星。"]},{"t":"孤凝","f":"七言绝句","c":["筠皮月静铺金屑，仙掌云寒砌玉花。","人在华胥初梦断，乱山满目一声鸦。"]},{"t":"宝慈寺","f":"五言绝句","c":["殿古涵烟冷，楼空得月多。","钟声巡远岫，塔影卧清波。"]},{"t":"岩下闻鸦","f":"七言绝句","c":["行绕松林不见鸦，只疑山后噪查查。","更移数步俄回首，缩脰蹲身立树丫。"]},{"t":"招贤道士","f":"七言绝句","c":["解鞍默默对斜晖，无限诗怀在翠微。","一句秋鸿来入耳，两行客泪下沾衣。"]},{"t":"易道录招饮 其五","f":"七言绝句","c":["名于瑚琏斯为贵，身与鸿毛孰较轻。","诗社近来多笔冢，醉乡何处得愁城。"]},{"t":"易道录招饮 其四","f":"七言绝句","c":["诗疵得似维摩病，酒圣能如孟子醇。","何事多时疏杖屦，亦缘避俗屏冠巾。"]},{"t":"易道录招饮 其三","f":"七言绝句","c":["素白见招真慷慨，苍黄欲赴又趑趄。","命存一定百年见，事要十全千古无。"]},{"t":"易道录招饮 其二","f":"七言绝句","c":["诗酒交游如骨肉，江湖聚散似云萍。","已烦鹤唳供头盏，且借岚光作画屏。"]},{"t":"易道录招饮 其一","f":"七言绝句","c":["竹风不断凉如水，山雨无声细似尘。","世事总归簪上雪，人生聊寄瓮头春。"]},{"t":"武夷有感 其十一 结末","f":"七言绝句","c":["道人心与物俱化，对景无思诗自成。","诗句自然明造化，诗成造化寂无声。"]},{"t":"武夷有感 其十 卧","f":"七言绝句","c":["岩下烟深人不来，白云寂寂掩苍苔。","松花落地鸟声寂，一枕清风送梦回。"]},{"t":"武夷有感 其九 坐","f":"七言绝句","c":["千山猿叫月如昼，万籁风号天正秋。","雾湿苍苔烟漠漠，白云飞梦过瀛洲。"]},{"t":"武夷有感 其八 住","f":"七言绝句","c":["月冷风清三径竹，猿啼鹤唳一窗云。","开门放入前山翠，试把星儿柏子焚。"]},{"t":"武夷有感 其七 行","f":"七言绝句","c":["两脚初收起暮烟，芒鞋竹杖翠云边。","东风解发阳春意，放出落花啼鸟天。"]},{"t":"武夷有感 其六 暮","f":"七言绝句","c":["碧云红树晚相间，落日乱鸦天欲昏。","人去采芝不知返，草庐空自掩柴门。"]},{"t":"武夷有感 其五 晓","f":"七言绝句","c":["风吹万木醒栖鹊，月落西山啼断猿。","云捲翠微深处寺，一声钟落碧岩前。"]},{"t":"武夷有感 其四 冬","f":"七言绝句","c":["几尺雪藏山径暮，一枝梅簇洞门春。","溪头昨夜冰寒绿，风捲彤云发晓嗔。"]},{"t":"武夷有感 其三 秋","f":"七言绝句","c":["雨馀秋藓几堆锦，日出朝葵千簇金。","对景适然发清啸，野猿惊泣绿杨深。"]},{"t":"武夷有感 其二 夏","f":"七言绝句","c":["莺唤绿杨抽嫩叶，蝶催碧藕发新花。","飒然一点薰风至，日落前山噪乱鸦。"]},{"t":"武夷有感 其一 春","f":"七言绝句","c":["雨霁烟凝正夕阳，子规啼断几人肠。","东风不动些情思，无限落花春自香。"]},{"t":"泊头场刘家壁","f":"七言绝句","c":["春深空度可怜宵，江岸风沙好寂寥。","人问孤舟多少恨，五更寒雨报芭蕉。"]},{"t":"泊舟听雨","f":"五言绝句","c":["人已就船眠，犬知何处吠。","雨来闹秋江，全似茶铛沸。"]},{"t":"泊舟顺济庙前","f":"五言绝句","c":["梧叶落满地，西风洗九天。","鹤声明月夜，曾此系吾船。"]},{"t":"炙灯","f":"七言绝句","c":["观里多时道士憎，只知贪酒百无能。","黄昏钟了无人迹，借得邻房一盏灯。"]},{"t":"牧童","f":"五言绝句","c":["杨柳阴初合，村童睡正迷。","一牛贪草嫩，吃过断桥西。"]},{"t":"画石二首 其二","f":"七言绝句","c":["直作壶中九华看，碧于簪玉小于拳。","好藏莫便令人见，恐有痴情似米颠。"]},{"t":"画石二首 其一","f":"七言绝句","c":["一片嵯峨堕碧空，嵚崎历落最玲珑。","从教把玩真堪醉，疑自当年栗里中。"]},{"t":"祈雨伏虎庵","f":"七言绝句","c":["梵相无言旱气奢，三农无饭欲蒸沙。","狻头香穗成禾穗，麈尾天花化雨花。"]},{"t":"织机","f":"七言绝句","c":["天地山河作织机，百花如锦柳如丝。","虚空白处做一疋，日月双梭天外飞。"]},{"t":"罗浮山上过铁桥","f":"七言绝句","c":["飞云顶下见罗浮，五色珍禽绕石楼。","行过铁桥猿啸罢，稚川丹灶冷飕飕。"]},{"t":"虱","f":"五言绝句","c":["裤里无供给，裈头尽受降。","赐之汤沐罢，投置不毛邦。"]},{"t":"话旧","f":"七言绝句","c":["风露三更月一帘，共君握手不能厌。","酒杯满泛榴花色，烛燄斜抽柳叶尖。"]},{"t":"剑池","f":"七言绝句","c":["人间无处著青蛇，池水清泠浸落花。","几度清风明月夜，怅然无语忆张华。"]},{"t":"南湖","f":"五言绝句","c":["已拾诗盈箧，犹如酒满船。","湖光清似镜，俯仰两青天。"]},{"t":"城楼晚望","f":"七言绝句","c":["女墙驾月子城东，暮色初来诗兴浓。","绿暗红稀春结局，望中白鸟入青峰。"]},{"t":"尝青梅","f":"七言绝句","c":["青梅如豆试尝新，脆核虚中未有仁。","勘破收香藏白处，冰肌玉骨是前身。"]},{"t":"幽兴","f":"七言绝句","c":["一春病酒废登临，风搅石楠花满林。","山色有无烟聚散，溪光动静鸭浮沉。"]},{"t":"幽居杂兴 其三","f":"七言绝句","c":["月来佐酒如随牒，花自从诗各寄名。","尽把烟霞归节制，闲中排日听泉声。"]},{"t":"幽居杂兴 其二","f":"七言绝句","c":["阳春有脚三杯酒，野战无哗一局棋。","见说王门堪炙手，抱猿弄鹤不曾知。"]},{"t":"幽居杂兴 其一","f":"七言绝句","c":["岸花洗面初收雨，江草摇头已怯风。","独立无聊聊送目，西边落日叫孤鸿。"]},{"t":"春词 其三","f":"七言绝句","c":["瘦沈皤潘莫自匆，花边有酒且从容。","春三二月东风里，莺百千声翠柳中。"]},{"t":"春夕与西林老月下坐 其一","f":"七言绝句","c":["燕子呢喃君得知，深谈实相妙难思。","久参贝叶云何梵，一见桃花更不疑。"]},{"t":"春夕与西林老月下坐 其二","f":"七言绝句","c":["一物言无也大奇，如何半夜却传衣。","于知见处生知见，在是非中起是非。"]},{"t":"春日自省 其二","f":"五言绝句","c":["雪洗桃花面，烟描柳叶眉。","与春同是梦，安用赏春为。"]},{"t":"春日自省 其一","f":"五言绝句","c":["燕语今生事，花开夙世红。","不知终日醉，何以谢春风。"]},{"t":"春日散策 其二","f":"五言绝句","c":["柳眼开何媚，蒲芽长得伸。","寒花方谒日，新燕已参春。"]},{"t":"春日散策 其一","f":"五言绝句","c":["水长二三尺，梅馀六七花。","明朝须不雨，今晚已成霞。"]},{"t":"春风 其四","f":"七言绝句","c":["远草将人双眼行，飞花误蝶乞流莺。","更饶一夜东风劣，且博三朝五日晴。"]},{"t":"春风 其三","f":"七言绝句","c":["底事东风苦欲寒，不教诗客纵游观。","无端虚把鞦韆送，落尽梨花似雪团。"]},{"t":"春风 其二","f":"七言绝句","c":["燕燕于飞引蝶狂，娇莺歌懒笑蜂忙。","庭前萱草台前竹，也学春风舞绿杨。"]},{"t":"春风 其一","f":"七言绝句","c":["一一须梢一雾珠，晓来雨意尚踌躇。","落花也避东风恶，水面相驱亸向隅。"]},{"t":"春兴 其七","f":"七言绝句","c":["娇烟嫩霭弄晴晖，谁见诗人太息时。","风主庭前花寿夭，水占溪上柳安危。"]},{"t":"春兴 其六","f":"七言绝句","c":["望中白鸟入空无，一带青山似画图。","宿雨初醒云半敛，垂杨微困水平铺。"]},{"t":"春兴 其五","f":"七言绝句","c":["细雨如毛暮霭浓，山光水色醉春空。","认来认去燕还舍，吹落吹开花使风。"]},{"t":"春兴 其四","f":"七言绝句","c":["晓日激昂山吐雾，东风从臾水生波。","燕才邂逅莺相款，花自将迎蝶见过。"]},{"t":"春兴 其三","f":"七言绝句","c":["茜草叶交萱草叶，桃花枝映李花枝。","馊风馂雨休相恼，放我水边林下嬉。"]},{"t":"春兴 其二","f":"七言绝句","c":["未忺盥栉且看云，空翠濛濛霁色分。","日线穿窗蜂透出，隔窗花影动欣欣。"]},{"t":"春词 其七","f":"七言绝句","c":["春色将穷诗未穷，开樽姑为慰东风。","偶然行到青苔上，尚有残英一片红。"]},{"t":"春词 其六","f":"七言绝句","c":["晴帘暖幕笑如烘，春事还归缥缈中。","红药一枝寒食过，东风万点海棠空。"]},{"t":"春词 其五","f":"七言绝句","c":["旦上襌衣试绿罗，情知春暮亦无何。","风吹一架荼蘼雪，酒恶频将玉蕊挼。"]},{"t":"春词 其四","f":"七言绝句","c":["柳困花慵风力轻，脱襌衣裌过清明。","唤晴唤雨鸠无准，飞去飞来燕有情。"]},{"t":"春词 其二","f":"七言绝句","c":["千红万紫竞繁华，莺燕多依富贵家。","上巳兰亭修禊事，一年春色又杨花。"]},{"t":"春词 其一","f":"七言绝句","c":["春光若海渺无边，日暮归来泛玉船。","红酽海棠红似雪，翠娇杨柳暗如烟。"]},{"t":"春雨","f":"七言绝句","c":["柳色烟光正斗青，桃花落尽杏花惊。","风从窗眼空中入，雨在檐前滴到明。"]},{"t":"春宵有感 其八","f":"五言绝句","c":["多愁君自尔，不乐我何曾。","西北山如削，明朝约共登。"]},{"t":"春宵有感 其七","f":"五言绝句","c":["命驾承千里，论文且一樽。","春高人易老，风雨闭柴门。"]},{"t":"春宵有感 其六","f":"五言绝句","c":["书来相借问，客至欲如何。","自草黄庭去，归来管割鹅。"]},{"t":"春宵有感 其五","f":"五言绝句","c":["月落知何处，夜长无了时。","幽人春自感，莺燕亦何知。"]},{"t":"春宵有感 其四","f":"五言绝句","c":["憎却堤边柳，青丝复尔长。","自怜愁里鬓，不觉暗中霜。"]},{"t":"春宵有感 其三","f":"五言绝句","c":["百念今何女，何年遂大刀。","瑶池春不老，谁复敢偷桃。"]},{"t":"春宵有感 其二","f":"五言绝句","c":["安得安期枣，如瓜恐不然。","楚江萍似斗，泰华藕如船。"]},{"t":"春宵有感 其一","f":"五言绝句","c":["春夜常如岁，何妨秉烛嬉。","百花俱中酒，万竹自吟诗。"]},{"t":"春宵酌雨","f":"七言绝句","c":["更无半点海棠飞，一听黄莺雨里啼。","啼得碧坛红药破，淡烟芳草满长堤。"]},{"t":"春晚","f":"五言绝句","c":["我怪东风黠，暗知春欲归。","尽将杨柳絮，剪作雪花飞。"]},{"t":"春晚忆故人","f":"七言绝句","c":["车痕马迹遍江湖，且捲琴书又草庐。","芳草两堤三月暮，故人千里一书无。"]},{"t":"春晚行乐 其三","f":"七言绝句","c":["晓雨初收翠霭浓，此番二十四番风。","忽惊春暮翻为雪，乃是杨花飞满空。"]},{"t":"春晚行乐 其二","f":"七言绝句","c":["今夜遥知春欲归，望春不极立多时。","草迷野渡东西岸，月挂寒松上下枝。"]},{"t":"春晴","f":"五言绝句","c":["宿霭萦馀冻，松阴挟嫩晴。","朝来花万福，莺奏起居声。"]},{"t":"枯松","f":"七言绝句","c":["霜鳞雪爪一枯松，恍似湖心见白龙。","想得吕仙曾点化，拿云攫雾欲腾空。"]},{"t":"柏子家风","f":"七言绝句","c":["山居剩得静乾坤，竹鼎时将柏子温。","会似赵州参得透，等闲莫与俗夫论。"]},{"t":"残春","f":"七言绝句","c":["昨日春光更水涯，水涯今日已春赊。","春归只道无踪迹，尚有青苔一片花。"]},{"t":"洞明轩","f":"七言绝句","c":["夜坐幽堂听玉泉，松号风吼不成眠。","蒲团里面真消息，猿叫千山月正圆。"]},{"t":"洞前亭","f":"七言绝句","c":["洞前春水漾桃溪，洞后数声青鸟啼。","二十四岩风雨夜，神仙过此话刀圭。"]},{"t":"洞庭庙","f":"七言绝句","c":["樯乌啼罢纸灰飞，神去神来人不知。","惟有金沙堆下水，东西南北任风吹。"]},{"t":"洞虚堂","f":"七言绝句","c":["青牛人去几千年，此道分明在眼前。","要识个中端的意，一堂风冷月婵娟。"]},{"t":"独步","f":"五言绝句","c":["月澹黄茅路，烟明红叶村。","有怀如阮籍，更赠一声猿。"]},{"t":"秋日书怀 其三","f":"七言绝句","c":["秋风秋雨索人诗，云放千山翠色奇。","重九数来还渐近，木犀开了不曾知。"]},{"t":"秋日书怀 其二","f":"七言绝句","c":["检点秋光莫问天，只从鸿雁见推迁。","未霜杨柳老多病，既雨芙蓉美少年。"]},{"t":"秋日书怀 其一","f":"七言绝句","c":["桂花已是上番香，枫叶飘红柿叶黄。","社日雨多晴较少，秋风昼热暮差凉。"]},{"t":"秋园夕眺","f":"七言绝句","c":["木犀倜傥散麸金，松举笙竽竹奏琴。","临水芙蓉自儿女，镜边刺绣晚沉吟。"]},{"t":"秋思","f":"七言绝句","c":["滴尽池荷无奈雨，吹翻井叶可怜风。","溪毛山骨犹无恙，尚有芦花对蓼红。"]},{"t":"绘莲 其二","f":"七言绝句","c":["浓淡色中匀粉腻，浅深痕上著胭脂。","华堂展处南薰起，一似西湖六月时。"]},{"t":"绘莲 其一","f":"七言绝句","c":["笔底荷花水面浮，纤毫造化夺工夫。","为谁画出生绡上，泰华山头玉井图。"]},{"t":"览镜","f":"七言绝句","c":["岁事軨㖃好送穷，头今未雪脸犹红。","一回览镜一回老，天已安排欲我翁。"]},{"t":"送别","f":"五言绝句","c":["十日九风雨，一春三别离。","予嗟吟骨瘦，子亦坐诗痴。"]},{"t":"送林古虚归闽","f":"七言绝句","c":["名落江湖二十春，江湖那个是知音。","于今拄杖挑明月，云满千山何处寻。"]},{"t":"送郑阳春","f":"七言绝句","c":["前身莫是郑安期，井灶重来迹已遗。","涧底菖蒲无可采，共君细读汉时碑。"]},{"t":"送郑道人归罗浮","f":"七言绝句","c":["铁作桥梁云作盖，石成楼观水成帘。","归时猿鹤烦传语，记取前回白玉蟾。"]},{"t":"送郭进之","f":"五言绝句","c":["避暑白云乡，茶甘齿颊香。","海城悲暮角，烟树淡斜阳。"]},{"t":"送晋上人游雁荡","f":"七言绝句","c":["岭外猿啼秋树月，林间鹤唳晓松风。","此行雁荡须参透，依旧归来玉几峰。"]},{"t":"重九","f":"七言绝句","c":["疏风冷雨北山南，时见归鸿度碧潭。","重九日人多是醉，两三枝菊总斜簪。"]},{"t":"闻子规","f":"七言绝句","c":["二十年前怯杜鹃，枕边时把泪珠弹。","如今老眼应无泪，一任声声到月残。"]},{"t":"闽中晓晴赏牡丹","f":"七言绝句","c":["晴窗冉冉飞尘喜，寒砚微微暖气伸。","唤醒东吴天外梦，化为南越海边春。"]},{"t":"首夏 其三","f":"七言绝句","c":["满目晴峦总是诗，诗情飞絮逐游丝。","雨肥碧涧落花水，风瘦青松啼鸟枝。"]},{"t":"首夏 其二","f":"七言绝句","c":["日与浮云相往还，落花啼鸟总相关。","初无东观北门梦，只在西山南浦间。"]},{"t":"首夏 其一","f":"七言绝句","c":["懒中倍觉我神清，烦恼如今叶似轻。","青士庭前销昼暑，苍官枕上送秋声。"]},{"t":"倚马观二鹤","f":"五言绝句","c":["对舞鸣仍和，双飞去复回。","归家千载远，丹灶付苍苔。"]},{"t":"倪梅窗喜神赞","f":"七言绝句","c":["燕颔虎头古班超，龙章凤姿晋嵇康。","高人心地本无象，风清月冷倪梅窗。"]},{"t":"冥鸿阁即事 其四","f":"七言绝句","c":["夜饮青莲居士家，高吟大笑对梅花。","饕杯自喜更筹缓，醉墨偏随烛影斜。"]},{"t":"冥鸿阁即事 其三","f":"七言绝句","c":["瑞香蓓蕾破寒晴，稚子呼为紫素馨。","万斛幽香量不尽，霜风吹送暮天青。"]},{"t":"冥鸿阁即事 其二","f":"七言绝句","c":["雪白霞红云色黄，晚风先办晓来霜。","吹开一路江梅蕊，薰作九天沉水香。"]},{"t":"冥鸿阁即事 其一","f":"七言绝句","c":["腊雪飞如真脑子，水仙开似小莲花。","睡云正美俄惊起，且唤诗僧与斗茶。"]},{"t":"夏日睡起","f":"七言绝句","c":["圆玉响中销日永，铿金徽外作风悲。","万蚁战酣山雨至，饥肠雷动且吟诗。"]},{"t":"夏日遣兴 其三","f":"七言绝句","c":["四壁青山翠打围，诗人坐久澹忘归。","桥边荷芰攲头立，水底蜻蜓仰面飞。"]},{"t":"夏日遣兴 其二","f":"七言绝句","c":["素馨蕊点粉描笔，红藕花开金镀杯。","乳燕新蝉相对语，诗人何日不亭台。"]},{"t":"夏日遣兴 其一","f":"七言绝句","c":["枕簟来寻瓜李盟，银床金井已关情。","牡丹芍药成前辈，茉莉素馨方后生。"]},{"t":"夏夜露坐","f":"七言绝句","c":["披襟岸帻藕花桥，一片哀鸿度碧霄。","新月出来真解事，嫩蝉吟得自无聊。"]},{"t":"徐仙","f":"七言绝句","c":["采樵有遇才三日，归路还家已十年。","自古得仙非苦节，此坑安得号黄连。"]},{"t":"徐处士写予真","f":"七言绝句","c":["心潜天地笑藏春，月佩云衿绝一尘。","前世率陀天上客，今生大宋国中身。"]},{"t":"徐道士水墨屏 其四","f":"五言绝句","c":["霜月沉青嶂，汀鸥卧白沙。","晓风删竹叶，秋雾补山丫。"]},{"t":"徐道士水墨屏 其三","f":"五言绝句","c":["乱山草斜出，危冈竹倒悬。","人家春树里，山色夕阳边。"]},{"t":"徐道士水墨屏 其二","f":"五言绝句","c":["人远看来短，山遥淡欲无。","水边渔舍密，天际客帆孤。"]},{"t":"徐道士水墨屏 其一","f":"五言绝句","c":["雁侧风前字，烟凝雨后情。","不知谁氏子，持钓立江城。"]},{"t":"扇","f":"七言绝句","c":["怀袖相忘去不能，也知轻薄恶蚊蝇。","南风虽汝持权柄，只恐秋风见汝憎。"]},{"t":"旅邸睡起","f":"五言绝句","c":["云为山积翠，雨倩草添青。","一觉南柯梦，俄然鸟唤醒。"]},{"t":"晓巡北圃七绝 其七","f":"七言绝句","c":["游人脚踏杏花泥，花片吹风点绮衣。","为复残春催杜宇，是他杜宇唤春归。"]},{"t":"晓巡北圃七绝 其六","f":"七言绝句","c":["雨馀花点满红桥，柳雪粘泥夜不消。","晓雾忽无还忽有，春山如近又如遥。"]},{"t":"晓巡北圃七绝 其一","f":"七言绝句","c":["隔水人家似画图，鬓边香露缀成珠。","日高丈五云犹宿，乌鹊已归三哺雏。"]},{"t":"晓巡北圃七绝 其四","f":"七言绝句","c":["池边弄水手犹冰，藕臂风寒更粟生。","柳叶春深槐叶浅，桃花夜暗李花明。"]},{"t":"晓巡北圃七绝 其三","f":"七言绝句","c":["蜂蝶如知春欲归，雨馀莺亦缕金衣。","东风尽把杨花剪，吹作满城轻雪飞。"]},{"t":"晓巡北圃七绝 其二","f":"七言绝句","c":["柳色花光映晓云，半窗红日已东升。","行人隔水自相语，无数莺啼闻不曾。"]},{"t":"晓巡北圃七绝 其五","f":"七言绝句","c":["非云为侣更无人，独倚雕墙诗思冥。","日色淡红烟色紫，山光浓绿水光青。"]},{"t":"晓晴 其二","f":"五言绝句","c":["月落松方暗，花蜚鸟正啼。","青山春窈窕，碧草晓凄迷。"]},{"t":"晓晴 其一","f":"五言绝句","c":["昨夜天成雨，今朝水满池。","睡酣浑不觉，想见竹声奇。"]},{"t":"晓醒追思夜来句 其四","f":"七言绝句","c":["竹林如洗静娟娟，雪意犹酣晓色鲜。","云缠山腰腰带缓，雨沾水面面花圆。"]},{"t":"晓醒追思夜来句 其三","f":"七言绝句","c":["孤云野鹤寄山家，不料寒空璨六花。","越样月明浑不夜，个般天气好分茶。"]},{"t":"晓醒追思夜来句 其二","f":"七言绝句","c":["茆屋萧然诗满怀，一天风雪白皑皑。","身如纸帐梅花梦，心似香炉柏子灰。"]},{"t":"晓醒追思夜来句 其一","f":"七言绝句","c":["孤梦归从偃月城，清寒入骨倚危亭。","雪花散作杨花片，酒色酤来竹叶青。"]},{"t":"栖真观","f":"七言绝句","c":["鞭雷斩孽震南昌，拔宅升天谒玉皇。","西岭双枫南瀑布，自言曾识许旌阳。"]},{"t":"栩庵力高士与同散步 其二","f":"七言绝句","c":["功名不直一杯水，富贵于我如浮云。","诗句清妍仍净远，游丝飞絮听缤纷。"]},{"t":"栩庵力高士与同散步 其一","f":"七言绝句","c":["老槐苍苍嫩槐绿，小麦青青大麦黄。","燕已生雏莺已去，落花不管蜂蝶忙。"]},{"t":"栩庵同步偶成","f":"七言绝句","c":["枯木冷灰甘寂寞，片云孤月自优游。","君生平事皆如梦，我两眉间不著愁。"]},{"t":"流憩","f":"七言绝句","c":["苍崖万仞倚空寒，一道飞泉泻半山。","到此倚栏聊植杖，少时款款入松关。"]},{"t":"润夫饭僧景泰相款信宿告归","f":"七言绝句","c":["梦中也学云峰路，未老来游蒲涧山。","无数老僧闲道士，笑人骑马出松关。"]},{"t":"烟中梅花","f":"七言绝句","c":["烟里梅花别是清，略无风动亦寒馨。","如焚古鼎龙涎饼，坐对幽窗水墨屏。"]},{"t":"荷池追凉","f":"七言绝句","c":["清晓无人知此凉，岸巾植杖立银塘。","晴霞烧眼收将敛，荷叶生风绿水香。"]},{"t":"荷花","f":"七言绝句","c":["小桥划水剪荷花，两岸西风晕晚霞。","恍似瑶池初宴罢，万妃醉脸沁铅华。"]},{"t":"莺","f":"七言绝句","c":["踏折海棠花一枝，一枝花露湿金衣。","捎将粉蝶直飞去，却在绿杨深处啼。"]},{"t":"课园夫 其一","f":"五言绝句","c":["已属畦丁了，都将菜甲耘。","数时稽食籍，醢芥又羹芹。"]},{"t":"酌贪泉因吊吴隐之 其三","f":"七言绝句","c":["晋人相扇以清名，何事因泉始立清。","清到饥寒妻子地，此清太不近人情。"]},{"t":"酌贪泉因吊吴隐之 其二","f":"七言绝句","c":["酌之一似取廉名，未酌泉时本自清。","向使无泉亦无语，不贪不酌更分明。"]},{"t":"酌贪泉因吊吴隐之 其一","f":"七言绝句","c":["人其禄仕为齑盐，溪壑民财饱未厌。","不识隐之心与口，酌泉依旧只清廉。"]},{"t":"陶弓手弃役入道","f":"七言绝句","c":["青黑文身志气豪，生擒六贼脱尘劳。","当年尚有弯弓手，射杀三尸入大罗。"]},{"t":"高祖圣师天台紫阳真人赞","f":"五言绝句","c":["元丰一皂吏，三番遭配隶。","空馀悟真篇，带些铅汞气。"]},{"t":"偶书 其二","f":"七言绝句","c":["绛阙清都何时到，沧海桑田谁与怜。","三十六天归路稳，撚花对酒一凝然。"]},{"t":"偶书 其一","f":"七言绝句","c":["手撚荼蘼缘酒恶，十二栏干凭一角。","归兴应如春样浓，前亭后亭花自落。"]},{"t":"偶作 其二","f":"五言绝句","c":["雪后竹君子，霜前松大夫。","梅残半点白，猿叫一声孤。"]},{"t":"偶作 其一","f":"五言绝句","c":["露滴中宵月，松摇古谷风。","三身红萏菡，四智碧芙蓉。"]},{"t":"寄王察院 其三","f":"七言绝句","c":["黄金台迥鸳鸿集，碧玉壶深日月长。","大隐从来在朝市，谪仙况复富文章。"]},{"t":"寄王察院 其二","f":"七言绝句","c":["恩怨荣污总不知，片云只鹤久相期。","驱磨花月三千界，断送风波十二时。"]},{"t":"寄王察院 其一","f":"七言绝句","c":["不读儒书读道书，故人听我自江湖。","君今一武登台省，我亦三清直殿庐。"]},{"t":"惜春","f":"五言绝句","c":["薄倖东风者，无心半点春。","桃花吹满地，片片似鱼鳞。"]},{"t":"晚吟 其二","f":"五言绝句","c":["山色重拈出，秋云似削平。","可怜松下路，月黑不堪行。"]},{"t":"晚吟 其一","f":"五言绝句","c":["山似诗肩耸，江如酒量宽。","云描秋色老，松写暮声寒。"]},{"t":"晚春遣兴二绝 其二","f":"七言绝句","c":["临临春去却成晴，花落无声片片轻。","一句杜鹃香国泪，半帘皓月故人情。"]},{"t":"晚春遣兴二绝 其一","f":"七言绝句","c":["不但风饕雨更尤，落英满地诉春愁。","诗人分韵留春处，一句韩诗七个阄。"]},{"t":"晚酌翛然阁","f":"五言绝句","c":["残暑犹拖尾，新凉恰打头。","酒方屯鲁郡，舞已彻伊州。"]},{"t":"晚眺","f":"五言绝句","c":["岭口云拖白，江头叶借绯。","西风来问罪，老火不须威。"]},{"t":"曹国舅赞","f":"五言绝句","c":["窃得玉京桃，踏断金华草。","白云满蓑衣，内有金丹宝。"]},{"t":"梅花","f":"五言绝句","c":["影上酥花峭，枝头蜡糁清。","姮娥约滕六，夜半过江城。"]},{"t":"梅花有叹","f":"七言绝句","c":["苍苔玉艳委西施，玉胆冰姿尚伯夷。","春色一般清浊异，梅花亦自有安危。"]},{"t":"梅花醉梦","f":"七言绝句","c":["纸帐梅花醉梦间，了无它想鼻雷鼾。","鸳愁凤恨不入枕，睡觉身疑在广寒。"]},{"t":"梧窗 其二","f":"七言绝句","c":["世事如尘扫又生，梧窗终日坐冥冥。","有时饮罢却行乐，立看风吹阁上铃。"]},{"t":"梧窗 其一","f":"七言绝句","c":["夜半山风响翠梧，一窗皓月照琴书。","试将笔架山头屋，问有清幽似此无。"]},{"t":"清静经","f":"七言绝句","c":["大地山河一卷经，拈来题目甚分明。","山花野草皆谈说，蠢动含灵侧耳听。"]},{"t":"渔舍","f":"七言绝句","c":["江上蓼花红似血，江头沙碛明如雪。","前山后山寂无人，一犬夜吠松梢月。"]},{"t":"盘云 其二","f":"七言绝句","c":["笔架山头一片云，盘旋岩谷不求伸。","时人只恐清风起，吹作皇都雷雨春。"]},{"t":"盘云 其一","f":"七言绝句","c":["今古无门闭是非，无心出岫已知机。","于今收拾归山谷，不逐春风上下飞。"]},{"t":"菜羹","f":"七言绝句","c":["一卷仙家煮菜经，宰夫失笑太官惊。","蓝田山里空餐玉，岂识闻韶别是清。"]},{"t":"萧侍郎故居","f":"七言绝句","c":["玉笥山前萧子云，手携白璧玩青春。","碧坛夜夜松风起，八十二人朝玉宸。"]},{"t":"雪中 其三","f":"七言绝句","c":["飞廉滕六逞寒威，费酒陪诗为解颐。","雪待夜深飞落尽，梅嗔风恶放开迟。"]},{"t":"雪中 其二","f":"七言绝句","c":["晓来红日尚羞明，四外彤云欲诈晴。","一夜九天开玉阙，六花万里散璚英。"]},{"t":"雪中 其一","f":"七言绝句","c":["朔风吹冷裂窗纱，重把罗帏绣幕遮。","青女先将霜起早，素娥始放雪飞花。"]},{"t":"雪窗","f":"五言绝句","c":["素壁青灯暗，红炉夜火深。","雪花窗外白，一片岁寒心。"]},{"t":"黄冈","f":"七言绝句","c":["海山千里起风沙，拂拂篮舆细雨斜。","云裹桂松连岫碧，自酤市酒慰蕉花。"]},{"t":"黄仙庵字谜","f":"七言绝句","c":["青红白黑欠中央，闻道西人已大方。","二十一人田下电，阿谁访之詹仲皇。"]},{"t":"寒食","f":"五言绝句","c":["日落千山暝，风吹一路香。","燕依花色紫，莺体柳丝黄。"]},{"t":"朝斗","f":"七言绝句","c":["夜楼一穗玉炉烟，飞入三天最上天。","朝罢满空风露晚，世人应是更贪眠。"]},{"t":"棘隐壁 其三","f":"五言绝句","c":["碧草正春风，雨晴竹落涕。","白鸟忽飞来，点破一山翠。"]},{"t":"棘隐壁 其二","f":"五言绝句","c":["幽鸟噪岩谷，寒烟锁薜萝。","忽遇金蟾蜍，无人自呵呵。"]},{"t":"棘隐壁 其一","f":"五言绝句","c":["苔空绿钱死，松老清阴瘦。","结庐卧白云，柏子烧春昼。"]},{"t":"棹歌九章寄彭鹤林 其七","f":"五言绝句","c":["黄昏杳无人，孤江但翠竹。","惟有白鹭鸶，伴我舟中宿。"]},{"t":"棹歌九章寄彭鹤林 其五","f":"五言绝句","c":["波心采莲女，流花近吾船。","移船入芦荻，吹笛下晴川。"]},{"t":"湖上偶成 其二","f":"七言绝句","c":["湖天清旷万缘虚，暂借僧房作宰予。","梦觉风凉归去晚，满空飞翠扑篮舆。"]},{"t":"湖上偶成 其一","f":"七言绝句","c":["葭蒲满荡起晴烟，总属霜鸥雪鹭天。","一片紫菱开十字，中间放过采莲船。"]},{"t":"湘江遇雨","f":"七言绝句","c":["骚人载酒泛潇湘，预约寒鸥立岸旁。","雨点斲蓬休作梗，浪声与枕始相忘。"]},{"t":"琴","f":"七言绝句","c":["夜静无云月似银，清宵鹤唳一伤神。","子期玉骨寒于雪，世上知音能几人。"]},{"t":"番阳旅寓留题","f":"七言绝句","c":["洞门深锁绿烟寒，来享浮生半日闲。","城北城南无老树，横吹铁笛过庐山。"]},{"t":"登爱阁有感","f":"七言绝句","c":["五六年前彭觉非，同登爱阁玩荷池。","如今再到还重省，十二阑干谩雨丝。"]},{"t":"紫溪偶成回文体","f":"七言绝句","c":["鹂黄并柳风飘絮，蝶粉粘花露浥香。","离别恨深深院静，少年人去去途长。"]},{"t":"董双成旧隐 其二","f":"七言绝句","c":["月恋梅窗呈水墨，风依竹槛奏笙竽。","金幡玉胜无从见，尚想云间唱步虚。"]},{"t":"董双成旧隐 其一","f":"七言绝句","c":["断霞残雨洗虹桥，群雁衔枚度碧霄。","半夜风鸣云里佩，乘鸾人弄月中箫。"]},{"t":"董楼","f":"七言绝句","c":["文章道德今谁似，事业功名我不无。","十载江湖一杯酒，夜深说与董归奴。"]},{"t":"集句赠王秀才","f":"七言绝句","c":["富贵必从勤苦得，名位岂肯卑微休。","劝君更尽一杯酒，与尔同销万古愁。"]},{"t":"韩湘子赞","f":"五言绝句","c":["白雪满空夜，黄芽一朵春。","蓝关归去后，问甚世间人。"]},{"t":"感兴 其二","f":"七言绝句","c":["酒兴诗狂似蝶蜂，终朝上下逐东风。","梁间燕共何人语，庭下花无百日红。"]},{"t":"感兴 其一","f":"七言绝句","c":["又见荷开满故园，夙红昨紫俨然存。","画梁飞燕前身赵，曲槛歌莺阿姊樊。"]},{"t":"感咏十解寄呈杨安抚 其四","f":"五言绝句","c":["上界足官府，大仙多拘束。","遂令东方朔，只恋殿前肉。"]},{"t":"感咏十解寄呈杨安抚 其八","f":"五言绝句","c":["鸡翘豹尾中，凤阁鸾台客。","何似许旌阳，西山煮白石。"]},{"t":"感咏十解寄呈杨安抚 其九","f":"五言绝句","c":["跃马西湖道，载酒湖水滨。","一蝶忽花下，招之论大椿。"]},{"t":"感咏十解寄呈杨安抚 其七","f":"五言绝句","c":["伊昔为句漏，其心在丹砂。","丹成遽仙去，不且判莺花。"]},{"t":"感咏十解寄呈杨安抚 其一","f":"五言绝句","c":["大隐在朝市，仙人好楼居。","方平今白发，未许见麻姑。"]},{"t":"感咏十解寄呈杨安抚 其二","f":"楚辞体","c":["身如云样轻，心似月兮皎。","何物堪赠君，一颗安期枣。"]},{"t":"感咏十解寄呈杨安抚 其十","f":"五言绝句","c":["青山犹古人，碧草亦大雅。","幽鸟话升平，陈抟何为者。"]},{"t":"感咏十解寄呈杨安抚 其六","f":"五言绝句","c":["酒专风月权，诗欠江山债。","恐是试长房，尘劳君少耐。"]},{"t":"感咏十解寄呈杨安抚 其五","f":"五言绝句","c":["玉女鸣珂佩，投壶不忆题。","刘安无复傲，殿殿叩星扉。"]},{"t":"感咏十解寄呈杨安抚 其三","f":"五言绝句","c":["风吹五花辇，露缀九光舆。","夜半红尘起，琴高失鲤鱼。"]},{"t":"感春","f":"五言绝句","c":["晴少春光浅，寒多酒力微。","一声山鹧过，数点海棠飞。"]},{"t":"新正 其三","f":"七言绝句","c":["一番桃李又春风，送古迎今事不穷。","南北故人鸿去外，东西野渡雪晴中。"]},{"t":"新正 其二","f":"七言绝句","c":["九重天上星三点，万顷波心月一钩。","醉有百篇来笔下，愁无半点到眉头。"]},{"t":"新正 其一","f":"七言绝句","c":["九天日月开黄道，十洞烟霞接紫清。","为问蟠桃当熟未，人间春草几枯荣。"]},{"t":"睡起","f":"七言绝句","c":["清似垂竿钓楚江，酒兵已退睡魔降。","霜风吹破梅花晓，雾月飞浮竹影窗。"]},{"t":"风雨","f":"五言绝句","c":["隔岸芦招手，沿溪柳拜人。","两庾黄竹路，水齧白沙津。"]},{"t":"蜗牛","f":"七言绝句","c":["有宅一区长自负，受田百亩不能耕。","壁间银篆方犹湿，早已枯然梦两楹。"]},{"t":"酬颜宣教","f":"七言绝句","c":["柳梢黄鸟韵绵蛮，风雨将春暗锁关。","镇日吟诗无好句，坐看乳燕语梁间。"]},{"t":"雷怡真小隐送春","f":"五言绝句","c":["天不欲留春，东君暗归去。","碧梧枝上看，潇潇风送雨。"]},{"t":"暮色","f":"七言绝句","c":["江烟漠漠月昏昏，一点渔灯贴岸根。","风搅长芦鸦睡起，游鳞惊动水花痕。"]},{"t":"瑶台散天花词 其三","f":"七言绝句","c":["翠幢绛节忽纷纷，空里笙箫节奏闻。","碧玉宫中花似雪，蕊珠殿下鹤如云。"]},{"t":"瑶台散天花词 其二","f":"七言绝句","c":["诸天綵女一双双，十二楼前并捧香。","太乙真人乘白鹤，云中端简候虚皇。"]},{"t":"瑶台散天花词 其一","f":"七言绝句","c":["夜半泠然御八风，下观四海气濛濛。","举头忽已三更上，上有琼楼十二重。"]},{"t":"疑潮","f":"七言绝句","c":["卧闻雨吼是潮奔，直恐横舟堕海门。","凡百可疑多若此，万今千古共谁论。"]},{"t":"蜡梅","f":"五言绝句","c":["破苍如凝蜡，粘枝似滴酥。","恍疑菩萨面，初以粉金涂。"]},{"t":"嘲杜鹃","f":"七言绝句","c":["杜宇声声盖自嗟，春残何事更天涯。","不归则是归还是，伊是无家或有家。"]},{"t":"墨竹","f":"七言绝句","c":["虚舟惠我一墨竹，纸上森森一枝玉。","展向庭前与鹤看，今宵不许枝头宿。"]},{"t":"醉作观音像仍为书赞 其三","f":"七言绝句","c":["花红柳绿菩提相，燕语莺啼般若宗。","更去补陀山上觅，云涛烟浪捲天风。"]},{"t":"醉作观音像仍为书赞 其二","f":"七言绝句","c":["顶戴弥陀呈丑拙，手持杨柳惹尘埃。","纵饶入得三摩地，当甚街头破草鞋。"]},{"t":"醉作观音像仍为书赞 其一","f":"五言绝句","c":["柳絮多头绪，桃花好面皮。","夫是之谓谁，东海比丘尼。"]},{"t":"醉吟 其二","f":"五言绝句","c":["醉掬山先走，行呼月后随。","欲眠梧影下，又恐白云知。"]},{"t":"醉吟 其一","f":"五言绝句","c":["松风吹我飞，手搦空中月。","笑指蓬莱山，可补银河缺。"]},{"t":"题光孝观","f":"七言绝句","c":["偶然骑鹤去游仙，来访泉山古洞天。","一剑当空又飞去，碧潭惊起老龙眠。"]},{"t":"题武夷 其五","f":"七言绝句","c":["山耸千层青翡翠，溪流万顷碧琉璃。","游人来此醉归去，几个亲曾到武夷。"]},{"t":"题武夷 其四","f":"七言绝句","c":["显道真人去不回，幔亭不见旧楼台。","曾孙倚著寒松立，日落风悲猿自哀。"]},{"t":"题武夷 其三","f":"七言绝句","c":["芳草暗分流水绿，老松刚借远山青。","独拈铁笛溪头立，吹与洞中仙子听。"]},{"t":"题武夷 其二","f":"七言绝句","c":["龙骧仙掌岩头水，鹤唳幔亭峰上云。","但得明窗尘一匕，跃身去谒武夷君。"]},{"t":"题武夷 其一","f":"七言绝句","c":["不见虹桥接幔亭，空馀水绿与山青。","客来剔出些奇胜，五曲溪头大隐屏。"]},{"t":"题郑通妙方丈","f":"七言绝句","c":["无争之棋两三局，自劝之酒一二杯。","但且任么随俗过，丹成云鹤自然来。"]},{"t":"题客省","f":"七言绝句","c":["炼就红铅不计斤，五湖四海十馀春。","今朝杖屦庐山下，雨笠烟蓑一个身。"]},{"t":"题胡子山林檎坡","f":"七言绝句","c":["洞宾踢碎金葫芦，夜半姮娥下蕊珠。","但见满天尽角角，不知春去鬼揶揄。"]},{"t":"题胡运干别墅 其二","f":"七言绝句","c":["博山一炷小蛇寒，无人独自坐蒲团。","柴门却倩冷风关，檐外白云时往还。"]},{"t":"题胡运干别墅 其一","f":"七言绝句","c":["闷来爱竹把花嫌，无事看山高捲帘。","好鸟一声飞过檐，清风著力送银蟾。"]},{"t":"题栖凤亭 其四","f":"七言绝句","c":["声传琴瑟风生枕，影泻琅玕月满庭。","白凤飞来枝外宿，夜深点破一林青。"]},{"t":"题栖凤亭 其三","f":"七言绝句","c":["潘氏亭前饮一宵，酒酣对竹啸琼箫。","不知栖凤来多少，凤去人归竹寂寥。"]},{"t":"题栖凤亭 其二","f":"楚辞体","c":["竹也多年管风月，凤兮几夜宿云烟。","林间有客吹箫去，竹化成龙凤入天。"]},{"t":"题栖凤亭 其一","f":"七言绝句","c":["亭前绿密玉成丛，凤宿枝头烟雨空。","箫管一声人未寝，满林明月浸清风。"]},{"t":"题桐柏观","f":"五言绝句","c":["淡月笼苍松，清流蘸脩竹。","水深蟾不设，长伴道人宿。"]},{"t":"题桐柏观","f":"七言绝句","c":["仙翁夜来扣林壑，约我明朝过南岳。","石坛对坐话松风，鹤唳一声山月落。"]},{"t":"题莫干山","f":"七言绝句","c":["封到半天烟霭间，一卷仙书一粒丹。","城南城北无老树，又吹竹笛过前山。"]},{"t":"赠黄亭虞丈","f":"七言绝句","c":["修爵固当修天爵，选官何似选天官。","青驺走遍皇都易，白鹤飞来绛阙难。"]},{"t":"题精舍","f":"七言绝句","c":["到此黄昏飒飒风，岩头只见药炉空。","不堪花落烟飞处，又听寒猿哭晦翁。"]},{"t":"题潘察院竹园壁","f":"七言绝句","c":["夜雨洗开千翡翠，春风撼碎万琅玕。","满林鸦鹊卧明月，铁笛一声烟正寒。"]},{"t":"题凝翠阁","f":"七言绝句","c":["日射新苔铸绿钱，山耸花屏草刺毡。","剩把苔钱买风月，山屏低拥草毡眠。"]},{"t":"赞历代天师 第一代祖师正一静应真君讳道陵字辅汉","f":"七言绝句","c":["云锦山前鍊大丹，六天魔魅骨毛寒。","一从飞鹤归玄省，烟雨潇潇玉局坛。"]},{"t":"赞历代天师 第七代讳仲回字德昌","f":"七言绝句","c":["当年辟谷炼仙丹，召雨呼雷譬似闲。","四海有人膺宝箓，笑携筇去鹤鸣山。"]},{"t":"赞历代天师 第九代讳符字德信","f":"七言绝句","c":["上饶山水甲江南，一锡横飞欲结庵。","忽遇至人烟霭外，归来无语隐松岩。"]},{"t":"赞历代天师 第二十一代讳秉字温甫","f":"七言绝句","c":["火腹金龟梦正疑，琳房初诞谪仙儿。","丹传祖印百来岁，执笏归仙地震时。"]},{"t":"赞历代天师 第二十七代讳象中字拱辰","f":"七言绝句","c":["仁皇恩赐紫衣时，方是宁馨七岁儿。","闲把洞章歌一阕，不知鸾鹤满天飞。"]},{"t":"赞历代天师 第二十九代讳景端字子仁","f":"七言绝句","c":["当年仙去鹤巢空，万壑千崖夕照红。","人在丹丘玄圃外，潇潇松桂夜来风。"]},{"t":"赞历代天师 第二十二代讳善字元长","f":"七言绝句","c":["参遍名山谒洞天，相逢却是活神仙。","归来换骨回阳日，屈指人间九十年。"]},{"t":"赞历代天师 第二十八代讳敦复字延之","f":"七言绝句","c":["棘围战罢笑归来，一寸功名心已灰。","白鹤何年归洞府，夕阳影里野猿哀。"]},{"t":"赞历代天师 第二十三代讳季文字仲归","f":"七言绝句","c":["玉盂祝水起波云，笔下雷声泣鬼神。","龙虎山前山后问，先生活尽几多人。"]},{"t":"赞历代天师 第二十五代讳乾曜","f":"七言绝句","c":["横握镆铘入洞天，洞天漠漠掩寒烟。","仁宗亲问金丹诀，笑指斜阳噪乱蝉。"]},{"t":"赞历代天师 第二十六代讳嗣宗","f":"七言绝句","c":["朱砂鼎里炼金晶，默祷天皇入紫冥。","月落半山丹井水，猿声惊断满天星。"]},{"t":"赞历代天师 第二十代讳谌字坚德","f":"七言绝句","c":["吸乾酒海一须臾，冠冕玄坛百岁馀。","不食人间烟火气，能传天上电花书。"]},{"t":"赞历代天师 第二十四代讳正随字宝神","f":"七言绝句","c":["人在犁锄烟水乡，结茅高卧小松岗。","敕封真静先生号，一卷仙经一炷香。"]},{"t":"赞历代天师 第二代嗣师讳衡字灵真","f":"七言绝句","c":["光和初载大丹成，有甚工夫事汉灵。","夜半玉舆飞紫露，春风春雨满阳平。"]},{"t":"赞历代天师 第八代讳迥字彦超","f":"七言绝句","c":["丹篆才书泣鬼神，年踰九十脱红尘。","至今岩上结庐处，夜半凤凰栖绿筠。"]},{"t":"赞历代天师 第十一代讳通字仲达","f":"七言绝句","c":["闭户凝神四十年，青鸾赤玺策云轩。","琼棺数月金躯冷，满室天香酹一樽。"]},{"t":"赞历代天师 第十七代讳顺字仲孚","f":"七言绝句","c":["贵溪一尉隐家山，静结茅庐三两间。","九十岁时尸解日，时人犹见是童颜。"]},{"t":"赞历代天师 第十九代讳修字德真","f":"七言绝句","c":["玉局瑶篇龙凤文，三元开度士如云。","翻身踏著蓬莱路，浴罢焚香自入坟。"]},{"t":"赞历代天师 第十二代讳仲常字德润","f":"七言绝句","c":["鹤书曾诏赴宸京，归作分形化景人。","昨日饮酣曾吐酒，醒来又薄瓮头春。"]},{"t":"赞历代天师 第十八代讳士元字仲良","f":"七言绝句","c":["神水华池养白鸦，玉炉进火结丹砂。","仙家妙用无人识，顷刻能开桃李花。"]},{"t":"赞历代天师 第十三代讳光字德昭","f":"七言绝句","c":["几年辟谷学飞行，挥破秋空一点青。","才到暮林风月夜，洞天隐隐步虚声。"]},{"t":"赞历代天师 第十五代讳高字士龙","f":"七言绝句","c":["丹台一点玉髯翁，千古天师张士龙。","招弄斸山诗技巧，吐吞风月酒神通。"]},{"t":"赞历代天师 第十六代讳应诏字治凤","f":"七言绝句","c":["一亩闲云独自耕，草庐寂寂诵黄庭。","又言辟谷归山后，月夜时闻铁笛声。"]},{"t":"赞历代天师 第十代讳子祥字鳞伯","f":"七言绝句","c":["满室神光夜欲阑，灵丹吐出掌中看。","当时鹤唳佳城外，空有霓裳掩玉棺。"]},{"t":"赞历代天师 第十四代讳慈正字子明","f":"七言绝句","c":["丹鼎能乾活水银，举家一念赡贫民。","空中动破云韶乐，白鹤飞来风雨春。"]},{"t":"赞历代天师 第三十一代讳时修字朝英","f":"七言绝句","c":["是个清都一散郎，凝神聚气炼丹阳。","片云孤鹤无踪迹，半夜风寒万里霜。"]},{"t":"赞历代天师 第三十二代讳守真字遵一","f":"七言绝句","c":["鹤颈龟腮骨已仙，星坛长啸诵琼篇。","自从阙下归仙后，一枕清风几万年。"]},{"t":"赞历代天师 第三十代讳继先字遵正","f":"七言绝句","c":["筑著成都人姓刘，丹成蜕迹入罗浮。","琼楼数纸御书在，虚静先生已掉头。"]},{"t":"赞历代天师 第三代系师讳鲁字公期","f":"七言绝句","c":["笑把铜章尹汉中，隐山斗米显神功。","魏兵四畔临河岸，弹指波心万丈峰。"]},{"t":"赞历代天师 第五代讳昭成字道融","f":"七言绝句","c":["数千里外露阳神，丹灶灰寒结紫云。","两虎归林人不见，数枝茵草鹤穿坟。"]},{"t":"赞历代天师 第六代讳椒字德馨","f":"七言绝句","c":["丹书玉札隐琅函，云几飞空鹤几骖。","告别门人归去后，夜来素月落寒潭。"]},{"t":"赞历代天师 第四代讳滋字元微","f":"七言绝句","c":["鄱阳策杖抵岩巅，旧有丹炉锁暮烟。","今古一双龙虎石，侍郎仙去是何年。"]},{"t":"赠云谷孔全道","f":"七言绝句","c":["凝神爽气炼金丹，七返从来有七还。","昨夜一声雷霹雳，不知人已在泥丸。"]},{"t":"赠观庵主","f":"七言绝句","c":["蹲鸱味美还师独，榾柮烟青喜我同。","拄杖出门谁会得，松梢浩浩啸天风。"]},{"t":"赠何画梅","f":"七言绝句","c":["一枝照夜向清寒，恍似孤山跂马看。","却恐春风咎毛颖，泄他消息貌他颜。"]},{"t":"赠何道人","f":"七言绝句","c":["汞虎铅龙炼气神，黄芽昨夜一枝春。","刀圭底事如何会，伏虎朱砂匮水银。"]},{"t":"赠别徐监观","f":"七言绝句","c":["晓来自点素馨汤，两朵莲花隔宿香。","夜醉至今犹未醒，荔枝取次对离觞。"]},{"t":"赠吴道士","f":"七言绝句","c":["延陵大士诗中虎，接武黄陈肩李杜。","无盐争敢陋西施，也向雷门声布鼓。"]},{"t":"赠张知堂","f":"七言绝句","c":["清河知堂武当来，左日右月双眼开。","高卧云堂留梦醒，笑骑白鹤归蓬莱。"]},{"t":"赠沙书先生","f":"七言绝句","c":["生蛇满地走如飞，入石三分未是奇。","掇取恒河归掌握，毫毛不动始知机。"]},{"t":"赠陈孔目","f":"七言绝句","c":["制锦堂前万事闲，掉头来入武夷山。","当年种放如能学，白鹤青云也不难。"]},{"t":"赠陈先生 其三","f":"七言绝句","c":["翻身趯倒玉葫芦，神水华池一夜枯。","蓦地夜行见月影，水晶盘里走明珠。"]},{"t":"赠陈先生 其二","f":"七言绝句","c":["木人手里挥泥剑，石女头边带铁花。","龙汉元年冬上巳，相逢一盏赵州茶。"]},{"t":"赠陈先生 其一","f":"七言绝句","c":["炯炯双眸古老锥，手提向上大钳锤。","蓦然寻著钟离老，捉住长髯问是谁。"]},{"t":"赠明讲师 其二","f":"七言绝句","c":["岂谓东吴得再逢，二俱老尽少时容。","来从上国莺花里，堕在辋川图画中。"]},{"t":"赠明讲师 其一","f":"七言绝句","c":["昔从师在月岩时，我过鹅湖即语离。","每见孤鸿每生感，不曾一日不相思。"]},{"t":"赠诗仙","f":"七言绝句","c":["学诗有似学仙难，炼句难于学炼丹。","换骨脱胎君有诀，炷香特特扣诗坛。"]},{"t":"赠相士徐碧眼","f":"七言绝句","c":["碧眼何须青白为，冰辞雹语不吾欺。","君看衮衮腰金者，曾见骚坛大将谁。"]},{"t":"赠徐钟头","f":"七言绝句","c":["楼上疏钟撞月明，五云影里一声声。","九天星宿皆朝斗，人世晓鸡浑未鸣。"]},{"t":"赠徐翔卿之别","f":"七言绝句","c":["桃花落地雨漫漫，子乃担簦过万山。","临别有些无尽意，篇诗送子到崇安。"]},{"t":"赠船稍","f":"五言绝句","c":["苦海无船渡，众生到岸难。","劝君齐著力，结取万人欢。"]},{"t":"赠葆元","f":"七言绝句","c":["弃儒为见儒多误，学道缘吾道化贤。","且把功名权架阁，抱琴随我去修仙。"]},{"t":"赠蓝琴士 其三","f":"七言绝句","c":["夜来莫说西山冷，见说庐山夏有冰。","直恐与君相别后，错听猿啸作琴声。"]},{"t":"赠蓝琴士 其二","f":"七言绝句","c":["逍遥阁下暮烟生，相对无言坐复行。","弹尽胡笳十八拍，床头剑吼月三更。"]},{"t":"赠蓝琴士 其一","f":"七言绝句","c":["江湖见说老蓝公，今日相逢在玉隆。","竹样精神梅样骨，况君梅竹在胸中。"]},{"t":"螺青山下皆地锦花","f":"七言绝句","c":["螺青山绾青螺髻，地锦花铺锦地衣。","雨过花娇山色茜，疑山解舞欲狂飞。"]},{"t":"蟋蟀 其二","f":"七言绝句","c":["秋暮何聊饮不多，素空皓月舞傞傞。","也知落叶风前拍，似应寒蛩砌下歌。"]},{"t":"蟋蟀 其一","f":"七言绝句","c":["白发秋来又几茎，萍蓬湖海困平生。","三更窗外芭蕉影，九月床头蟋蟀声。"]},{"t":"霞隐","f":"五言绝句","c":["仙翁栖紫霞，颜童鬓不华。","客来问玄机，笑指菖蒲花。"]},{"t":"露珠","f":"五言绝句","c":["秋河一滴露，夜堕即珠然。","吹入玉盘里，走盘如许圆。"]},{"t":"八月三日即事","f":"五言律诗","c":["烟冷浑沾水，溪清可数鱼。","鸦翻千点墨，雁草数行书。","今日征帆下，前年上国初。","诗盟寒复讲，无酒兴何如。"]},{"t":"十月十四夜","f":"五言律诗","c":["十月十四夜，灯寒燄寸长。","披衣临曲水，把笔向清霜。","月透诗情冷，风吹醉面凉。","故人知得否，空断早梅肠。"]},{"t":"三月芙蓉","f":"七言律诗","c":["岂论春夏及秋冬，事事皆由造化工。","谁道一生无好运，何缘三月见芙蓉。","骚人犹恐东风误，醉眼真疑芍药红。","便是重阳开未晚，且传好意取欢容。"]},{"t":"三华院还丹诗","f":"七言律诗","c":["绛宫无事绝尘埃，坎虎离龙战几回。","白雪飞空铅蕊绽，黄云覆鼎汞花开。","龟蛇抱一成丹药，乌兔凝真结望胎。","夜半瀛洲寒月落，冷风吹鹤上蓬莱。"]},{"t":"三衢舟次 其二","f":"七言律诗","c":["困兽犹强剑未红，少年羞见白蘋风。","心寒赤县神州远，兴入胡庭沙漠浓。","谁谓阿蒙犹洛下，未应老亮更隆中。","年来弓矢浑无用，只好江头射暮鸿。"]},{"t":"三衢舟次 其一","f":"七言律诗","c":["柿叶翻黄枫叶红，一江涨起芦花风。","水清石露沙痕瘦，日落雨来云意浓。","诗思动摇帆影里，梦魂摇兀橹声中。","黄昏有底愁如织，南外寄书无去鸿。"]},{"t":"乞纸寄诸葛桂隐","f":"七言律诗","c":["翰墨膏肓二十年，才亲笔砚便垂涎。","东阳鱼卵寒霜幅，嵊县溪藤妙雪笺。","一日秃除千兔颖，霎时磨尽万松烟。","洛阳市上今无价，直欲昂头写碧天。"]},{"t":"大都督制侍方岩先生召彭白饮于州治之春野亭因和苏子美韵","f":"七言律诗","c":["夕阳花木丹青活，烟月山林水墨昏。","碧缕倦飞萦宝鼎，红波惊涨溢金樽。","掀髯醉接君谟笔，击缶吟招子美魂。","因逐尚方双舄至，亦随桃李入春园。"]},{"t":"小桃源","f":"五言律诗","c":["好事开三径，栽花满一园。","前头平俯水，里面曲通村。","自有鸠夫妇，仍多竹子孙。","醉归迷去路，题作小桃源。"]},{"t":"不赴宴赠丘妓","f":"七言律诗","c":["舞拍歌声妙不同，笑携玉斝露春葱。","梅花体态香凝雪，杨柳腰肢瘦怯风。","螺髻双鬟堆浅翠，樱唇一点弄娇红。","白鸥不入鸳鸯社，梦破巫山云雨空。"]},{"t":"为李县尉寿","f":"七言律诗","c":["浪萍风絮客他乡，喜者青春鬓未霜。","到处烟霞成莫逆，如今山水已相忘。","子还真个为仙尉，我定终身作懒王。","何似著鞭铅汞事，笑骑云外鹤翱翔。"]},{"t":"云霄庵会宿","f":"五言律诗","c":["春自如情暖，夜何如话长。","酒醨成水淡，诗妙夺花香。","月出星转闹，云行山似忙。","起来携素手，拥被视农秧。"]},{"t":"五更解酲梅竹之间徘体","f":"五言律诗","c":["宿鸟能传语，残风且点心。","山情怜澹坐，月色笑孤斟。","惊我梅花睡，闻他竹叶吟。","清归无所得，得句贵如金。"]},{"t":"午饭罗汉寺","f":"七言律诗","c":["林间一径似惊蛇，中有禅关隐紫霞。","烟锁苍松遮寺额，风摇翠竹撼檐牙。","客来寂寞盘香穗，饭罢从容瀹茗花。","到此徘徊归去晚，夕阳挂树一声鸦。"]},{"t":"天谷庵","f":"七言律诗","c":["半天突出一奇峰，小小茅檐滋味浓。","夹道新松招夜月，满林幽竹唤秋风。","迎人野鸟间关语，恼客岩花烂熳红。","策杖且随流水去，柴门时倩白云封。"]},{"t":"天籁堂","f":"七言律诗","c":["到此令人玉骨寒，四围紫翠玉回环。","玲珑苍壁竹敲竹，重叠画屏山间山。","猿笛晓闻冥漠外，松涛夜吼有无间。","我将唤起陈知白，蜕却尘躯跨綵鸾。"]},{"t":"太虚堂","f":"七言律诗","c":["满堂冷静爽精神，不著人间一点尘。","檐鹊噪风呼薄晚，庭花飘露落残春。","华胥上国今无梦，龙汉元年古有身。","香篆飞从窗外去，云梢孤鹤唳何人。"]},{"t":"月岩","f":"七言律诗","c":["素娥飞下碧霄间，别馆嵌空万仞寒。","不是高悬青玉玦，直疑斜捧烂银盘。","云根朴朔兔相似，灌木参差桂一般。","说与长风休送上，千秋留与往来看。"]},{"t":"月窗写闷","f":"五言律诗","c":["不分庭前柳，长啼月下乌。","半生嗟命薄，中夜正心孤。","勋业看双鬓，歌吟在数须。","从今闲草马，休得更江湖。"]},{"t":"见浙翁琰禅师","f":"七言律诗","c":["谓师有道国人皆，何必文殊更五台。","棒喝交驰聊复尔，离微不犯亦奇哉。","且言风动还幡动，莫问船来与陆来。","不道相逢不相识，尽教寒拾笑咍咍。"]},{"t":"见懒翁 其一","f":"七言律诗","c":["一掬精神迥出尘，懒翁自是不凡人。","渊明松菊径犹绿，灵运池塘草正春。","已把芝田栽枸杞，不将苔砌展蒲轮。","家传衣钵归龙凤，自指冰壶嗣颍滨。"]},{"t":"见懒翁 其二","f":"七言律诗","c":["坡仙何日跨鲸归，公是苏家老白眉。","把剑舞残杯内酒，抚琴弹破笔头词。","桂林种德不知岁，福海流长无尽时。","他年翁若回蓬岛，稳把青毡付阿谁。"]},{"t":"北山","f":"七言律诗","c":["驿酒沽来满满斟，现成诗句不须寻。","轻云阁雨风声软，淡霁笼云日影沉。","夹路栀花香野水，隔山杜宇响乔林。","草庵饭了从容睡，门外通衢无古今。"]},{"t":"归雁亭","f":"七言律诗","c":["嗟予尚未发星星，今日杯茶归雁亭。","几见霜翎巢白草，数行云足篆青冥。","方将寄字来苕霅，莫便翻身过洞庭。","握手亭前话今古，仇池仙墨有馀清。"]},{"t":"归雁亭","f":"七言律诗","c":["坡仙曾此缕归程，归雁因而扁此亭。","草劲风刚苕水绿，水枯雪老弁山青。","霜翎去去宾沙漠，云足翩翩影洞庭。","渠亦偶来还自去，弋人何用慕冥冥。"]},{"t":"玉壶轩","f":"七言律诗","c":["玉壶四榻静无尘，琴上无徽笔有神。","诗债已还休骨瘦，酒冤今醒但眉颦。","清风吹鹤梧桐晓，明月啼猿杨柳春。","见说玉楼新架就，紫皇有诏日来频。"]},{"t":"玉壶睡起","f":"七言律诗","c":["白云深处学陈抟，一枕清风天地宽。","月色似催人起早，泉声不放客眠安。","甫能蝴蝶登天去，又被杜鹃惊梦残。","开眼半窗红日烂，直疑道士夜烧丹。"]},{"t":"白云庵","f":"五言律诗","c":["宿雾恋乔木，落花粘瘦枝。","鸟声人静处，山色雨来时。","霁月成相约，凉风解见知。","僧房安一枕，海气濯冰肌。"]},{"t":"白石岩","f":"七言律诗","c":["平野巉然石一拳，千崖万岫翠相连。","鸟飞不到疑无路，云与齐高直接天。","下面仰看岩是屋，上头仍有玉为泉。","李仙丹熟山魈遁，尚有宸章寄紫烟。"]},{"t":"立秋有感","f":"五言律诗","c":["流年急似箭，日月跳如丸。","炎皇初解印，白帝又弹冠。","方旦喜无暑，教人又怕寒。","人生只如许，不觉鼻头酸。"]},{"t":"再会薛黄庭","f":"五言律诗","c":["别来真梦耳，相对各潸然。","一向于湖海，如今更市廛。","知心能有几，顾影独兴怜。","自叹吾衰矣，犹期子勉旃。"]},{"t":"劣隐","f":"七言律诗","c":["世态炎凉觉鼻酸，洞门空掩绿烟寒。","仗三尺剑临风舞，把一张琴对月弹。","斫竹数竿容水过，倚松半日执经看。","山林心绪得闲处，好炼长生不死丹。"]},{"t":"华阳堂二咏 其二 会云堂","f":"七言律诗","c":["不著人间一点尘，满堂尽是学仙人。","衣衫总带烟霞色，杖屦相随云水身。","铁笛横吹沧海月，纸袍包尽洞天春。","而今会聚十方客，认看何人是洞宾。"]},{"t":"华阳堂二咏 其一 华阳堂","f":"七言律诗","c":["幕天席地做生涯，凡圣同居气象佳。","拨过浮山供醉眼，斩新风月入诗怀。","花间自舞三台鹤，竹外空歌两部蛙。","不是道人多计较，是渠诸圣早安排。"]},{"t":"年踰弱冠又多锦瑟之一弦身堕尘樊未彻玉霄之半日醉怀无奈顾影自怜抱明月以兴悲向西风而思远谩拈秃兔姑慰心猿寄鹤林友","f":"七言律诗","c":["夜凉莫听野猿哀，觉我枯肠转九回。","淅淅秋风吹性水，淹淹暮雨滴心灰。","自怜孤影青灯下，曾作神霄故吏来。","若待此生尘债足，凤凰閤下已青苔。"]},{"t":"戏联回文体","f":"五言律诗","c":["水连天渺渺，山映月亭亭。","尾棹依凫渚，头船过蓼汀。","鬼神号暝壑，烟雾霭疏棂。","美酝浮觞玉，轻衣拂剑星。"]},{"t":"早秋诸友真率相聚","f":"七言律诗","c":["白帝如今已有权，骄阳退壁渐凉天。","兑支一霎风来享，供送三更月与眠。","山水秋来浑是画，宾朋酒后总成仙。","暗蛩弹镊知何处，远树长川忽眇绵。"]},{"t":"有怀","f":"五言律诗","c":["紫绮轻裘稳，青绫广被长。","明珠怀夜月，孤剑匣秋霜。","气魄今诸葛，襟期旧子房。","西风一长啸，草木正凄凉。"]},{"t":"有赠","f":"七言律诗","c":["云锁蓬莱海接天，琪花瑶草簇春烟。","三千年里桃初实，十二楼前月正圆。","白日尘埃飞不到，青冥风露冷无眠。","共君既饱胡麻饭，一棹归欤弱水船。"]},{"t":"次水帘洞韵","f":"七言律诗","c":["天上真珠直下垂，更无钩箔惹尘埃。","青鸾白鹤从教入，紫诏黄封不用来。","夜月祇为苏邝照，晚风端与葛黄开。","纵饶展挂长千尺，莫掩罗浮紫翠堆。"]},{"t":"次李侍郎见赠韵","f":"七言律诗","c":["家居琼馆海山隅，腹内包藏三教书。","明月清风为活计，蓬头跣足走寰区。","玉炉丹熟斟琼醑，金阙朝回唱步虚。","要识我侬真面目，广寒宫里看蟾蜍。"]},{"t":"次黄提刑雪韵","f":"七言律诗","c":["久晴忽尔雨丝丝，既雨还晴亦不疑。","滕六假宁催入局，赵衰回避乞寻医。","捣霜碾雹些来个，剪水雕冰片子时。","一夜悄然飞到晓，满天满地化琉璃。"]},{"t":"次韵王将仕","f":"七言律诗","c":["诗坛勍敌我何堪，只把新诗著意参。","韵险有如行栈閤，句香何止食馀甘。","江寒风落馀章谬，鸟过身轻一字惭。","饭了相陪閒笑语，锦囊非我许谁探。"]},{"t":"次韵东坡蒲涧寺 其二","f":"七言律诗","c":["陈踪行览寺门前，自取椰瓢酌冷泉。","山下果然无白地，洞中尽自有青天。","更谁识得安期事，且去参他景泰禅。","冠盖如云自来往，如今何处有神仙。"]},{"t":"次韵东坡蒲涧寺 其一","f":"七言律诗","c":["满山红白福桑花，蒲涧深中尽可家。","景泰得泉从卓锡，安期种枣说成瓜。","岂无仙化羊如石，尚有书踪壁似鸦。","一饭招提共僧语，法华经里问牛车。"]},{"t":"次韵宋秀才","f":"七言律诗","c":["昼弄朱曦夜弄蟾，知他何处地行仙。","殿前昔奏三千字，腰下曾缠十万钱。","得句直疑无李白，草书真个过张颠。","有时兴发临风舞，饮似长鲸吸百川。"]},{"t":"次韵彬上人见惠","f":"七言律诗","c":["象轮何事过毗耶，诗窍禅关事一家。","自古行春难尽美，非风即雨辄成差。","我文柔似三眠柳，君句清如六出花。","应悟己公茅屋下，拟之早已涉河沙。"]},{"t":"次韵紫岩潘庭坚 其二","f":"七言律诗","c":["何人皮里有阳秋，谁绢能包得许羞。","早趁黄书丞相押，莫空白了少年头。","既无顾恋于人己，便请清闲袖手休。","岂必灭秦安汉后，始来寻个赤松游。"]},{"t":"次韵紫岩潘庭坚 其一","f":"七言律诗","c":["人情不似吴笺厚，世路常如蜀道难。","两鬓已将沾雪白，寸心尚自炳枫丹。","君还有意凭谁说，我亦无言把剑看。","相对一窗风打雪，通红榾柮谩烧残。"]},{"t":"红梅","f":"五言律诗","c":["人赋红梅少，予诗为补遗。","霞融姑射面，酒沁寿阳肌。","太洁遭时妒，独醒为众疑。","漫随春色媚，自保岁寒姿。"]},{"t":"舟中遣兴二首 其二","f":"五言律诗","c":["暮树烟凝翠，秋花雨著黄。","万松罗谷口，一鹤点山阳。","霜叶梦零乱，云山望杳茫。","眼稍林下寺，髣髴数支郎。"]},{"t":"舟中遣兴二首 其一","f":"五言律诗","c":["江水皱寒绿，山花蓓淡黄。","断云漫远浦，归雁背斜阳。","客恨何凄寞，诗怀堕渺茫。","人生本萧散，我欲问渔郎。"]},{"t":"舟行西湖诗赠诸友","f":"七言律诗","c":["二十年来云水身，今凡七度踏京尘。","丝长岁月能多少，粟大功名徒苦辛。","白日戏陪人世事，绿烟锁断洞门春。","云岩月岫今何处，一听猿声一怆神。"]},{"t":"舟行适兴","f":"七言律诗","c":["天知一舸过扶胥，排办千山作画图。","暮霭催诗归彩笔，秋光入酒透冰壶。","篙头点水月破碎，云脚行天星有无。","岸柳江枫共招手，西风吹我出贲隅。"]},{"t":"过林灵素坟","f":"七言律诗","c":["众僧莫怨赵归真，此是容成太玉君。","始末四年曾就日，相将五秩即腾云。","帝心俾立神霄教，州额由升应道军。","泉石依然冠剑冷，至今雷电禦松坟。"]},{"t":"初冬即事","f":"七言律诗","c":["支颐默默靠柴扉，顿放诗题塞翠微。","三径寒松含宿雨，一川衰草卧斜晖。","孤烟白处丫峰露，乱叶红边个鸟归。","触目园林已如洗，菊花犹著郁金衣。"]},{"t":"初至肇庆府砚岩","f":"七言律诗","c":["峡口青门束碧流，天生双剑割清秋。","可怜柳叶黄如此，曾见芦花白也不。","本意买舟归楚国，此行为砚访端州。","渴来欲吸三江水，洗出胸中万斛愁。"]},{"t":"别句呈庚契吴高士","f":"七言律诗","c":["一笑相逢在翠微，绿槐高柳借凉时。","只将水竹烟云兴，说与风花雪月知。","日落三杯无事酒，人闲八句自然诗。","来朝云过青山外，回首空闻猿鹤悲。"]},{"t":"别李仁甫","f":"七言律诗","c":["君向星江结草庐，我来抵掌笑相于。","三杯碧液涨瓷盏，一缕青烟缠竹炉。","剑舞春风花烂熳，琴弹夜雨竹萧疏。","明朝拄杖知何处，猿叫千山月满湖。"]},{"t":"别蒋都辖用归雁韵","f":"七言律诗","c":["别来不觉八周星，过尽长亭又短亭。","霜雁贴天飞去去，弋人何事慕冥冥。","梅开春信宾南国，草劲秋声警虏庭。","我亦年来还慷慨，亭前一笑万山青。"]},{"t":"即事寄紫元","f":"五言律诗","c":["老雨饯秋菊，孤烟酝暮岚。","雁惊十月北，梅早一枝南。","往事风吹帽，良宵月挂簪。","时哉亦难得，我已到无参。"]},{"t":"呈万庵十章 其四 火候","f":"七言律诗","c":["无位真人炼大丹，倚天长剑逼人寒。","玉炉火煅天尊胆，金鼎汤煎佛祖肝。","百刻寒温忙里准，六爻文武静中看。","有人要问真炉鼎，岂离而今赤肉团。"]},{"t":"呈万庵十章 其一 归山","f":"七言律诗","c":["生死轮回第几番，尘尘劫劫不曾闲。","一潭湛绿是非海，千尺粉青人我山。","性地灵苗思水国，心天明月掩云关。","衣中珠子无寻处，今且随邪炼大还。"]},{"t":"呈万庵十章 其九 冲举","f":"七言律诗","c":["自从踏著涅槃门，一枕清风几万年。","弱水蓬莱虽有路，释迦弥勒正参禅。","谁将枯木岩前地，放出落花啼鸟天。","两个泥牛斗入海，至今消息尚茫然。"]},{"t":"呈万庵十章 其五 沐浴","f":"七言律诗","c":["药炉丹鼎火炎炎，六贼三尸怕令严。","无去无来无进退，不增不减不抽添。","爱河浪静浮朱雀，觉海波深浸白蟾。","一自浴丹归密室，太阳门下夜明帘。"]},{"t":"呈万庵十章 其十 参同","f":"七言律诗","c":["道人家在海之南，来访庐山老万庵。","露柱灯笼同请举，僧堂佛殿总和南。","山河大地自群动，蠢动含灵共一龛。","齑瓮里鱼淹未死，此香炷向活瞿昙。"]},{"t":"呈万庵十章 其三 炉鼎","f":"七言律诗","c":["须信先天事事无，阴阳陶铸此形模。","真空平等朱砂鼎，虚彻灵通偃月炉。","九窍可风坛墠暖，二时失火药材枯。","只兹一点无明燄，炼出人间大丈夫。"]},{"t":"呈万庵十章 其二 采药","f":"七言律诗","c":["五蕴山头多白云，白云深处药苗芬。","威音王佛随时种，元始天尊下手耘。","石女骑龙攀雨㼌，木人驾虎摘霜芸。","不论贫富家家有，采得归来各一斤。"]},{"t":"呈万庵十章 其八 金丹","f":"七言律诗","c":["佛与众生共一家，一毫头上现河沙。","九还七返鱼游网，四谛三空兔入罝。","混洗何年曾结子，虚空昨夜复生花。","阿谁鼎内寻丹药，枯木岩前月影斜。"]},{"t":"呈万庵十章 其七 脱胎","f":"七言律诗","c":["青天白日一声雷，撒手悬崖了圣胎。","有眼如盲光烁烁，无绳似缚笑咍咍。","黄金殿下千株柳，碧玉堂前万树梅。","辜负鸳帏人寂寞，秦楼宴罢盍归来。"]},{"t":"呈万庵十章 其六 温养","f":"七言律诗","c":["金翁姹女结亲姻，洞口桃花日日春。","拾得一轮天上月，炼成万劫屋中珍。","黄婆即是母之母，赤子乃其身外身。","龙汉元年消息断，威音前面更何人。"]},{"t":"呈沈同知","f":"七言律诗","c":["三面俱江一面湖，古今画作水晶图。","门临车马红尘道，身在冰霜碧玉壶。","何道两山俱翠紫，霅苕二水合清污。","岸头笑与黄冠语，为问东林沈在乎。"]},{"t":"张子衍为至德知观鄢冲真求诗","f":"七言律诗","c":["一簇楼台水上居，琅风韵竹动笙竽。","鱼龙飞舞半帆雨，鸥鹭眠呼两岸芦。","雪覆高低春玉树，月明表里夜冰壶。","渔郎倚棹桃花落，认得扶桑宫殿无。"]},{"t":"张进甫静寮","f":"五言律诗","c":["脱俗卧云眠，胸中别有天。","壁间五六榻，屋上两三椽。","风月真滋味，溪山旧面缘。","静中有真静，猿啸暮林边。"]},{"t":"张道士鹿堂","f":"五言律诗","c":["清梦绕罗浮，羽衣延我游。","新茶寻雀舌，独芋煮鸱头。","春鹤饮药院，夜猿啼石楼。","丹炉犹暖在，聊为稚川留。"]},{"t":"快轩书怀","f":"七言律诗","c":["满树牡丹相次红，客来不放酒杯空。","三分春色二分去，一处风光是处同。","柳絮打残连夜雨，桃花飞落五更风。","与君饮到如泥烂，我欲明朝杖屦东。"]},{"t":"步虚四章 其一","f":"五言律诗","c":["昔在神霄府，飞云步玉天。","玉天三十六，六梵聚飞仙。","太帝升烟殿，东皇驾凤軿。","真灵来亿万，听演太灵篇。"]},{"t":"泛舟松江","f":"七言律诗","c":["白酒黄封冽以妍，鲈鱼买得一双鲜。","舟行无浪无风夜，人在非晴非雨天。","醉熟不知天远近，梦回但见月婵娟。","垂虹亭下星如织，云满长洲草满川。"]},{"t":"泛舟黄桥归庐山","f":"七言律诗","c":["清风为我送归船，数粒青松起薄烟。","帆影惊飞秋水雁，橹声搅断夕阳蝉。","几人家在溪头岸，一片云生水底天。","满眼良朋无好酒，此心已挂九江边。"]},{"t":"卧病","f":"七言律诗","c":["故故抽身入翠微，头昏背痛便相随。","只今得病缘身有，待我无身更病谁。","天际寒云糊远岫，松梢归鹤客枯枝。","青灯独照黄昏影，且自扶头强赋诗。"]},{"t":"和主簿家兄赠别韵","f":"七言律诗","c":["接耳交肩话绮疏，扶摇九万此南图。","对床风雨人皆有，协韵埙篪我独无。","偶尔诗家鸿雁行，为今酒岛鹡鸰徒。","情知一舸鸱夷去，临欲出门灯影孤。"]},{"t":"和张紫微韵题清虚庵","f":"五言律诗","c":["鸡犬声村市，烟霞古洞天。","晨坛凝玉露，夜井浸珠躔。","凤翼团宸画，龟趺负古镌。","于湖诗去后，今昔几千篇。"]},{"t":"夜宿太清悟真成道宫","f":"七言律诗","c":["朱楼紫殿贴晴空，前后千峰更万峰。","蝶殢秋花黄淡伫，猿啼晓树翠溟濛。","断霞烟重苔粘露，薄暮云兴夜起风。","醉倚玉栏弄明月，嗟嗟身世等萍蓬。"]},{"t":"奉呈天谷","f":"七言律诗","c":["底事英人便养高，角鹰放了弃弓刀。","六壬八遁成韬晦，四塞三边娄绎骚。","九十日秋凉气少，一千年事乱时多。","长歌大笑不对饮，奈此水光山色何。"]},{"t":"奉酬陈宫教","f":"七言律诗","c":["落魄逍遥一醉仙，笑携藜杖夕阳边。","三年睡法应须得，九蕴仙方妙不传。","骤雨猛催今日作，老苔为锁异时镌。","偶来水绿红花野，自与庐山亦有缘。"]},{"t":"怡斋","f":"七言律诗","c":["逸士幽居松竹林，小堂偃枕北山阴。","夜深冷月寒蓬户，晓起清风爽楮衾。","把剑更餐杯内酒，收书动破壁头琴。","自从一见羲皇面，千古谁知养浩心。"]},{"t":"武昌怀古十咏 其七 江汉亭","f":"七言律诗","c":["西风黄叶满秋城，水鸟飞无沙碛腥。","淮浪白如头似白，沔山青与眼俱青。","何人得见莲花女，此地空馀江汉亭。","一自郑生双佩断，幽情渺在蓼花汀。"]},{"t":"武昌怀古十咏 其九 西塞","f":"七言律诗","c":["落尽桃花水满湖，西山西塞长新蒲。","斜风细雨今如许，青笠绿蓑谁又无。","圣主龙飞邦有道，醉仙睡到日高梧。","何时尧舜无巢许，我也人乎粘壁枯。"]},{"t":"武昌怀古十咏 其四 吴王宫","f":"七言律诗","c":["不将胆命付周郎，安得儿孙见太康。","三国兴亡成梦事，一川烟草断人肠。","黄旗紫盖伊巴蜀，翠殿朱楼自武昌。","纵谓西山非王气，金陵能得几时王。"]},{"t":"武昌怀古十咏 其五 灵竹寺","f":"七言律诗","c":["孝之一字协天伦，信可通天感鬼神。","霜满竹林安得笋，心倾泪雨自生春。","祇闻郭巨曾埋子，岂得曾参亦杀人。","凿隧及泉愚尔耳，斯人盍是舜之臣。"]},{"t":"武昌怀古十咏 其三 赤壁","f":"七言律诗","c":["不说江山笑老权，尽称造化戏曹瞒。","飞乌绕树孤回首，断戟沉沙怒激湍。","豪杰已随霜叶尽，兴亡尽付浪花翻。","画堂莫唱坡仙赋，战骨草中吟夜寒。"]},{"t":"武昌怀古十咏 其六 奇章台","f":"词","c":["登台日费万缗钱，宾从如云剑履骈。","食鼎歌钟移楚地，貂金佩玉整唐天。","缅怀?钺熊旂里，尚有冰辞雹语传。","偃月堂中人用事，牛家僧孺得称贤。"]},{"t":"武昌怀古十咏 其十 南浦","f":"七言律诗","c":["越禽胡马易空疏，水远天长梦亦迂。","南北故人鸿去外，古今陈迹雨晴初。","云连碧草别愁黯，风眇绿波征骑孤。","三径凄凉一杯酒，夜深重读寄来书。"]},{"t":"武昌怀古十咏 其一 南楼","f":"七言律诗","c":["凭暖朱栏醉已酥，楼前眼缬望中疏。","汉阳草树看来短，淮岸渔家淡欲无。","薄暮鸦翻千点墨，晴空雁草数行书。","多情庾亮吟魂远，风泛芦花秋满湖。"]},{"t":"武昌怀古十咏 其二 黄鹤楼","f":"词","c":["白云黄鹤迹成遗，何独当年丁令威。","洞里不知朝市改，人间再到子孙非。","笛声吹断秋江黯，月影飞来夜漏稀。","大醉倚楼呼费?，蓬莱山下几斜晖。"]},{"t":"武昌怀古十咏 其八 鹦鹉洲","f":"七言律诗","c":["无人为叫祢平原，表祖粗人岂识文。","鹤在鸡群怀月露，豹将虎变欠风云。","凤凰池上才方酒，鹦鹉洲边已自坟。","道大不容才见忌，渔阳挝断不堪闻。"]},{"t":"泊头圆照堂","f":"五言律诗","c":["脱白来求法，披缁去出家。","此心如水月，结屋老烟霞。","翠长真如竹，黄开般若花。","寄言刘铁磨，自识赵州茶。"]}]};